quests[63614] = { id = 63614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapon in Hand", description = "A moment, {name}.\n\nI threw my axe Dra'gora at Helya during our first encounter in the Maw, and I haven't seen it since. If this is truly where she commands her forces, then perhaps it's held here.\n\nI crafted that weapon in Nagrand, and it reminds me of many good days spent beside my family there. I want to feel its weight in my hands once again.", progress = "I threw my axe in the heat of the moment...", completion = "Thank you, {name}. I feared my axe was lost forever.", objectives = "Find Thrall's axe, Dra'gora.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63615] = { id = 63615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clip Their Wings", description = "The skies are dark with Helya's kyrian followers. If we do not thin their numbers, Zerekriss and our aerial allies may have difficulties pushing forward.\n\nI've noticed that the Mawsworn often use magical chains. We could turn their equipment against them and tear them down from the sky.", progress = "We need to clear out the skies before we can begin the real assault.", completion = "Our foes will learn that even the skies are no longer safe for them.", objectives = "Use Mawsworn Chains to kill 6 Helsworn Soulbreakers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63616] = { id = 63616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Job Done Right", description = "We should be clear to start the assault.\n\nSignal the Zerekriss. Let us show them the might of a Maldraxxian necropolis and the combined armies of the Shadowlands!", progress = "Nothing can stand against the might of Maldraxxus!", completion = "We have our opening. It is time to push ahead.", objectives = "Signal the Zerekriss and start the assault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63617] = { id = 63617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bending Bars", description = "In all the chaos, the gates of the upper hold have been left open. If we slip through, they might not even notice us until it is too late.\n\nOne of Helya's lieutenants stands between us and Helgarde Keep. End them.", progress = "We need to get through that gate.", completion = "Now to sow chaos here.", objectives = "Slay Ironkeeper Salryx.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63618] = { id = 63618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Maldraxxus Does Best", description = "Every enemy we vanquish here is one our army does not have to contend with. We will make sure they will not soon forget the true purpose of Maldraxxus. Show them what happens to those we deem a threat towards the Shadowlands.\n\nKill every Mawsworn in sight.", progress = "Each Mawsworn we defeat is one less that will bother our forces in Korthia.", completion = "They were foolish to think they could cross blades with us.", objectives = "Slay 10 Mawsworn in upper Desmotaeron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63619] = { id = 63619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forsworn and Forgotten", description = "Wait... I know you! The Maw Walker!\n\nMy brothers and sisters have been twisted... tainted. Some took power willingly from Helya, but others resisted. Now all of us are forced to submit to her power.\n\nI escaped when the fighting started, but most of the remaining Forsworn are being subjected to horrific rituals.\n\nPlease, I beg you to free them. Then we will return to Bastion and submit to the Archon's judgment.", objectives = "Free 5 Forsworn Prisoners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63620] = { id = 63620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Traitor's Due", description = "Vyraz has been a constant thorn in Maldraxxus's side since he betrayed us. As Baroness of the House of the Chosen, it is my duty to see this threat eliminated... and the murder of Margrave Krexus avenged.\n\nAs the Primus said, we must remove the head from this snake.\n\nThe time to strike is now!", progress = "Vyraz is a stain upon Maldraxxus as long as he still draws breath.", completion = "<Draka spits on the corpse of Vyraz.>\n\nAnd with that traitor's end, Maldraxxus will be unified once again!", objectives = "Kill Vyraz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63621] = { id = 63621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pulling His Chain", description = "They call this one the Keeper of Chains. Do not underestimate his power. He has bound nearby souls in preparation for an attack against our position.\n\nI need you to eliminate this threat, Maw Walker, before it moves against our forces.", progress = "Have you eliminated this threat?", completion = "I knew we could count upon you, {name}.", objectives = "Eliminate the Keeper of Chains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63622] = { id = 63622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory in Our Name", description = "With Helya and Vyraz taken care of, we have achieved a major victory against the Mawsworn today. It is also a showing of what the combined might of the Shadowlands looks like.\n\nWe should return to Korthia before something else arises.", progress = "We have struck a blow against the Jailer's forces. Take your time to recover before the next strike.", completion = "There is no doubt that we will need to put pressure on Desmotaeron once again.\n\nThe witch of the Val'kyr will not let us walk free if she can help it.", objectives = "Return to the Primus at Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63623] = { id = 63623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filling an Empty Throne", description = "Maw Walker.\n\nIn my long absence, you have done much to bring order and strength back to the necrolord covenant. In recognition, I invite you to witness a ceremony.\n\nReturn with me to my seat of power in Maldraxxus. It is time I rewarded one who was most loyal to our cause.", completion = "This is the first step toward the restoration of Maldraxxus.", objectives = "Return to the Seat of the Primus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63624] = { id = 63624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Roads We Walk", description = "The armies of Maldraxxus are strong. They will recover from Vyraz's transgression. \n\nThe first thing we must do is rebuild. Maw Walker, stand witness to a new era for Maldraxxus!", progress = "Did you speak with each of our leaders? The army has much to celebrate.", completion = "We must all move forward. The Shadowlands relies on our strength.", objectives = "Witness Draka's promotion ceremony.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63625] = { id = 63625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Here's an Axe, Get to Work!", description = "Our troops are meeting stiff resistance! Maw Walker, grab a weapon and take the fight to them!\n\nEliminate the Mawsworn forces and their commander defending these gates.", completion = "Victory will be ours, Maw Walker!", objectives = "Eliminate 15 Mawsworn forces and Commander Mallamort.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63638] = { id = 63638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Turn Our Backs", description = "That's Sylvanas and her Mawsworn dealt with... for now.\n\nBut we need to hurry and make sure that the Queen and her sigil are safe! \n\nThe Winter Queen was just outside the Heart of the Forest, protecting the stolen wildseeds from the Maw.", progress = "The forest answers.", completion = "Ardenweald depends on the cycle. Without these spirits, what purpose would there be?\n\nI could not let the Jailer's forces destroy what we have fought so hard to protect.", objectives = "Check on the Winter Queen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63639] = { id = 63639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Oribos", description = "Ardenweald has withstood the unrelenting force of the Maw.\n\nBut it was still not enough.\n\nReturn to our allies in Oribos. There must be an answer for this loss, and action taken.", completion = "The Jailer has begun his attack on Oribos.\n\nWhat I have feared the most has come to pass.", objectives = "Return to Tal-Inara in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63644] = { id = 63644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dread Tidings", description = "The threat the nathrezim pose to our forces must not be underestimated. They are cunning, rivaling the best veterans of the House of Eyes, and we do not know their full plan.\n\nAmong the venthyr there is one whose wrath scourged the nathrezim from the Shadowlands for many thousands of years. \n\nI ask you travel to Sinfall, seek out Prince Renathal, and deliver to him this missive. I shall send one of my own spies, the Baroness Vashj, to meet you there. Make use of her experience with the nathrezim.", progress = "Dread tidings indeed.", completion = "The nathrezim have returned? I dared not imagine they would ever grow so bold again.\n\nA shame they have not learned in their exile, and return to us as enemies instead of family.", objectives = "Speak with Prince Renathal at Dawnkeep in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63645] = { id = 63645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dawnkeep Prisoner", description = "Oh, you have not heard the news yet.\n\nWe have him. Sire Denathrius, Master of Revendreth, imprisoned within his own blade.\n\nWe managed to best him during one of our recent raids of Castle Nathria.\n\nIt took an army of unparalleled valor and preparation. It took skill and wealth. It took a miracle.\n\nAnd so the redeemer shall be redeemed. Would you like to know more?", progress = "Never underestimate bravery when it is backed by weapons and armor of legendary make.", completion = "It may take ages upon ages, but we shall remind Denathrius of his purpose, and remind him how to be beautiful in his craft once again.\n\nThis place is strong with the Light. Few venthyr can tolerate such power for long without succumbing to it. A fitting place to teach uninterrupted.", objectives = "Learn of Sire Denathrius' fate from Prince Renathal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63646] = { id = 63646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Convoy of the Covenants", description = "A new sigil for the Venthyr would require all seven medallions to forge.\n\nThe Primus was correct. The person we need is the Stonewright. Her grievances against the Unseen could fill a library and she holds the last of the medallions we need. I believe you and I are long overdue in convincing her to join our cause.\n\nI will make the arrangements. We shall go properly this time, with gifts and diplomacy. \n\nYou should warn Chelra, she will want to arrange an escort.", progress = "What do you bring me, Maw Walker? Be advised I have no patience for deception and am not above feeding messengers to the gargons.", completion = "Hmm. A letter from the Primus himself? I had wondered what had become of that old tyrant. \n\n<Glances over the proffered letter.>\n\nI... see.", objectives = "Gather the Envoys and ride to Dominance Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63647] = { id = 63647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unseen Guests", description = "Dreadlords.\n\nOf course. Of course they would come back now of all times. I half suspected they returned during the drought. \n\nI was not entirely convinced you were not one, the first time I saw you. They have gotten more clever over the eons since they fled Revendreth. \n\nBut not clever enough... I think.\n\nCome, Maw Walker. Follow me and do not make a fuss. Keep your weapon ready. The envoy you brought is not as well intentioned as you might have thought.", completion = "Chelra was a nathrezim the entire time I knew her? \n\nEven in death I must still contend with the schemes of the nathrezim. I have grown too trusting in my penance.", objectives = "Join the Stonewright as she investigates the Envoy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63648] = { id = 63648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nal'ragas", description = "The Stonewright's medallion must not stay in the hands of the nathrezim. \n\nFrom what the Accuser explained of our mission, the medallion is required if we wish to forge a new sigil for the Venthyr. I have no doubt that is why Nal'ragas and her ilk executed their ambush now.\n\nThe medallions are not subtle magic, and their affect on this realm is easily tracked. I suggest we give chase and eliminate this Nal'ragas before she can be reinforced.", completion = "I have spoken with the Stonewright. Chelra fell to the master when I was a prisoner of the Maw. \n\nShe was my friend and protector through countless ages, and I did not even know she had been slain, her identity stolen.\n\nOne more sin for Denathrius to atone for.", objectives = "Track down and defeat Nal'ragas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63649] = { id = 63649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spy vs Spy", description = "Nathrezim. Dreadlords. The Unseen Guests.\n\nCall them what you will, they are a race that was crafted to be the greatest collection of spies and infiltrators in all of reality, once upon a time. \n\nTheir intrusion has underestimated three things. Kael'thas Sunstrider, Baroness Vashj, and {name}!\n\nI have brought a tool Kael'thas and I used to detect nathrezim when we served under Illidan. And I am the matron of spies!\n\nLet us hunt these intruders down.", progress = "Who says death is without its little pleasures.", completion = "The venthyr have grown complacent, unwilling to acknowledge the reality that nathrezim might return. The same blindness left them exposed to Denathrius' treachery. \n\nThey will be far more vigilant now.", objectives = "Track down and defeat 5 Dreadlord Infiltrators.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63650] = { id = 63650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "De-Infiltration", description = "Mal'Ganis.\n\nIt has been many ages since I have said his name. And now I find we must hunt him down.\n\nIf he has the Medallion of Wrath then there is nowhere he can hide. We can use the other medallions we have recovered to locate him.\n\nJoin me in Sinfall and bring your dreadlord hunting party. I suspect we will have need of them.", completion = "The nathrezim may not be venthyr, but nor were they crafted from souls. In many ways, they are more my siblings than my fellow venthyr.\n\nA shame what they have chosen to become.", objectives = "Meet Prince Renathal in Sinfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63651] = { id = 63651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cryptograms", description = "If the nathrezim have infiltrated Sinfall they will be communicating, and not just through hand gestures or spoken words. They like to use magical written messages concealed by a simple cantrip, invisible to the average observer.\n\nHowever, I have developed an incantation that should allow you to see these messages.\n\nFind these cryptograms and bring me their contents. I can translate them if they are beyond your understanding.", progress = "If the nathrezim have a flaw it is that they assume they are the only ones who get better over time.", completion = "This does not make sense. Their goals seem too wide spread. My assumption was that they had been planning to steal my medallion to deny us a new Sigil of the Venthyr, but it would appear their designs go beyond that.\n\nWhat are they really up to? Here, you can have a translated copy.", objectives = "Transcribe 10 Infernal Cryptograms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63652] = { id = 63652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The \"Unwelcome\" Guests", description = "Chelra, I mean Nal'ragas, would not have been working alone. We must assume the worst, that not all of our friends and allies are who they seem to be.\n\nIt will take time for the Court of Harvesters to render our detection ritual. While we do so we will be exposed. I ask that you use the techniques you employed at Dominance Gate within Sinfall to root out any nathrezim within our ranks. \n\nGood hunting.", completion = "Subterfuge and counter-insurgence was never my strong suit. We always had souls sent here that were far better than I at such tasks.", objectives = "Eliminate 3 nathrezim inside Sinfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63653] = { id = 63653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of a Crown", description = "We are ready.\n\nThe Court of Harvesters shall use the power of the medallions we have gathered thus far to locate the Medallion of Wrath. So long as they have not removed it from the realm we should be able to divine its presence.\n\nThis is not an easy ritual--the nathrezim specialize in avoiding detection. When you see the path, take it and move with speed.\n\nAnd when you find them, wait for us before you engage.", completion = "I will not suffer my medallion in the hands of these unwelcome guests.", objectives = "Track the path to the Medallion of Wrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63654] = { id = 63654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nathrezim", description = "The Medallion of Wrath is more than just a powerful artifact. In the hands of a nathrezim it could be used to shape this realm to their dark purpose. What is more, while they hold it we are denied the ability to forge a new sigil.\n\nThey already nearly destroyed the Ember Ward with their reckless schemes. I will not have my medallion used for their ends.\n\nCome, let us get it back.", completion = "This is worse than anything I could have anticipated.", objectives = "Recover the Medallion of Wrath from the nathrezim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63655] = { id = 63655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medallion of Wrath", description = "Maw Walker. I will march with my stoneborn into the depths of the Maw and rend the head off every nathrezim I find there.\n\nHowever, Revendreth is still too strategic in this war to lose out of misplaced vanity. \n\nTherefore, as Harvester of Wrath, the second of that title, I offer you my medallion for safe keeping and utilization while I wage this war.\n\nUse it to empower the Harvesters so they can prevent Denathrius from simply returning and regaining control with a snap of his fingers.", progress = "<The platform surges with power as it feels the proximity of the medallion.>", completion = "<Inserting the medallion in the socket tugs violently at your soul as the energies link, flooding a sense of will and intent into everything around you unlike any other energy you have experienced before. \n\nTogether, the Harvesters rule Revendreth uncontested.>", objectives = "Bring the Medallion of Wrath to the dais in Sinfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63656] = { id = 63656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Meaning of Wrath", description = "I will gather my forces and dispense a portion to Korthia immediately. I will also see to it that they are provided the tools Baroness Vashj and Kael'thas were able to conjure so that we might further defend against nathrezim incursions.\n\nOther duties require my attention before I can descend on Korthia. I must secure Dominance Keep against further infiltrators.\n\nI suppose the Primus will want an update. You may tell him you were successful.", completion = "Your strength in battle remains uncontested. Today, though, you prove your strength of diplomacy. \n\nI have already issued orders for the deployment of the Stonewright's forces. Well done in bringing her into the fold.", objectives = "Report to the Primus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63659] = { id = 63659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreadlords!", description = "This is the fifth dreadlord I have found infiltrating our forces this week. Unchecked they can cause tremendous damage to our foothold here.\n\nIn life I learned how to identify these creatures from a demon hunter. It makes it far easier for me to locate them, but I cannot be in all places at once.\n\nWe must report these findings to the Primus.", completion = "More dreadlords? I should have suspected the fangs of Denathrius would find their way here again.\n\nI am pleased to know that despite their setbacks in my absence, the House of Eyes has not lost their sight.", objectives = "Speak with the Primus in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63660] = { id = 63660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opening the Maw", description = "The Jailer has gained another sigil, and his forces actively assault Oribos.\n\nBolvar Fordragon and Draka of Maldraxxus suggest taking the fight to the Jailer.\n\nTo do so, we need a way for their forces to safely come and go from the Maw.\n\nThis was considered impossible before you arrived, but now I believe we have a chance.\n\nI must examine your anima to see if this is truly what the Purpose wills.", progress = "I do not do this lightly, Maw Walker.", completion = "I do not do this lightly, Maw Walker, but we have no choice.\n\nWe must open a gateway to the Maw.", objectives = "Allow Tal-Inara to examine your anima.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63661] = { id = 63661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Link to the Maw", description = "The Fatescribe is certain that a second waystone has emerged in the Maw. It falls to you to locate it. \n\nI will create an anchor here in Oribos that links to your anima. Once you attune yourself to the waystone, this anchor will be bound to it.\n\nIf you are successful, the covenants will be able to send their forces inside and safely leave the Maw again.\n\nUse what resources you have within the Maw to find this waystone.\n\nGood luck, mortal. May the Purpose guide us all.", progress = "You have that look about you, Maw Walker. \n\nThe one that tells me you are about to ask for my help.", completion = "Normally, I would consider your request bothersome and insulting.\n\nBut recent events have led me to believe that your proposal may prove beneficial to both of us.", objectives = "Ask Ve'nari about the location of a second waystone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63662] = { id = 63662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysteries of the Maw", description = "The Maw is changing, mortal. And with change comes opportunity.\n\nThe Jailer has pulled a realm that was hidden deep within the Shadowlands into the Maw. It is a location of some interest to me, but I do not wish to approach it alone.\n\nThe Mawsworn are swarming the area, you see. There must be something of value that they seek.\n\nI have a safe enclave nearby. Accompany me there and I may be able to help you find that waystone you're looking for.\n\nDo we have a deal?", completion = "The Jailer desperately wants something here, yet his precious Eye cannot breach its defenses.\n\nOh well. Shall we?", objectives = "Travel with Ve'nari to the site of the new landmass within the Maw", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63663] = { id = 63663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korthia, the City of Secrets", description = "We are on the threshold of attaining our desires, Maw Walker.\n\nYour grand waystone cannot be far off. Of course, my needs are much more modest. A bit of useful information here, a priceless relic there...\n\nI will survey the area to see if there is anything useful--or hazardous--nearby. Then we can proceed.", completion = "I must find out more about you, Maw Walker.", objectives = "Have Ve'nari scan the area, then investigate whatever is found.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63664] = { id = 63664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get to the Point", description = "Our position near the bridge to the Altar of Domination is under heavy attack! We can not afford to lose the ballista we have set up there.\n\nMaw Walker, I need you to defend that position till our troops can push forward!", progress = "Is our position safe?", completion = "Victory will be ours, Maw Walker!", objectives = "Defend the forward position inside Perdition Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63665] = { id = 63665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opening to Oribos", description = "The prophecies told us that one day this dormant waystone would be needed by a  Maw Walker. That it would prove crucial to the fate of the Shadowlands.\n\nIt seems that day has come.\n\nDraw upon the anima within you to activate this waystone. It will then be usable by all those who aid your cause.\n\nIf, as you say, Tal-Inara has created an anchor in Oribos, then that anchor will bring you back to us.\n\nGo, {name}. Inform your allies that the Maw awaits... and that Korthia needs their help.", completion = "Well done, {name}. I am eager to learn of this realm pulled into the Maw.\n\nIt is time to begin our assault on the Jailer's forces.", objectives = "Activate the waystone and travel to Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63669] = { id = 63669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Somebody Feed Kevin", description = "My family of slimes is always hungry for anima. Thankfully the bodies of the defeated here are a good source!\n\nThe more the slimes consume the larger they grow. Then what remains of the fallen will become part of our wonderful, happy family.\n\nTake Kevin and let him consume fallen enemies till he is fully grown, then unleash him upon our foes!", completion = "Victory will be ours, Maw Walker!", objectives = "Consume 8 fallen enemies to grow Kevin to full size.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63671] = { id = 63671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favor: The Nathrezim Documents", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", objectives = "Bring The Nathrezim Documents to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63672] = { id = 63672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cry From the Heart", description = "<The voice of Ysera emanates from the scroll as you read the words.>\n\n{name},\n\nThere is a matter of great importance which requires your help. Please meet me at the Heart of the Forest as soon as you can.", completion = "Thank you for coming so swiftly, {name}. Ardenweald is in need of your help.", objectives = "Meet Ysera at the Heart of the Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63673] = { id = 63673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Amid Houses", description = "I have good news, {name}. With the covenants working more closely together, Huln's hunt has found greater success. He has solid leads on two more Night Warriors here in the Shadowlands.\n\nHe wishes for you to meet him in Maldraxxus about the first. Huln awaits you at the Sepulcher of Knowledge.\n\nHurry, {name}. Elune's power rips at Tyrande's essence. I do not know how much longer she can hold on.", progress = "I am glad to hunt by your side once more, {name}.", completion = "My continuing hunt for more Night Warriors has brought me here, {name}. Together we will track them down and ask for their help.", objectives = "Find Huln Highmountain in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63674] = { id = 63674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By Your Leave", description = "I have a task set before me by my Baroness, Lady Vashj. With assistance, my vengeance would be swift. But she must approve of your help as well as my release to assist you with your task.\n\nGo to the Seat of the Primus. There we will speak with her.", progress = "Good. You move swiftly.", completion = "With your assistance I should be able to clear my list quickly.", objectives = "Meet with Lady Vashj at the Seat of the Primus, and request Khaliiq's help.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63675] = { id = 63675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Cannot Run", description = "Zelmany was integral in the fall of my Margrave.\n\nSin'Dane believes he is trying to gather forces loyal to Kel'Thuzad so they might help him in his next plot.\n\nWe should look for clues to his location and then slay him.", progress = "The traitors cannot run!", completion = "One of the ringleaders is dead but I will not be satisfied until they are all dead.", objectives = "Collect clues and then slay Zelmany.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63676] = { id = 63676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Cannot Hide", description = "There are those who held their affiliation with Kel'Thuzad secret even after he made his move. They too were involved in the fall of my Margrave, and they too shall die.\n\nI have one name, Drava'ora, but there are more. Sin'dane had indicated these traitors carry marks of favor. She doesn't know who has them so we'll start killing until we find them.\n\nThe rest will see the example made.", progress = "Those that remain will be scared into line.", completion = "Traitors cannot hide.", objectives = "Recover Marks of Kel'Thuzad's favor and slay Drava'ora.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63677] = { id = 63677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Can Only Die", description = "The last name on my list is a lich named Fal'zinge.\n\nSin'Dane has been keeping a close eye on him to learn more of what Kel'Thuzad is planning next. \n\nShe wishes for Fal'zinge's execution to be brutal. \n\nWe will find him in the Exoramas in the House of Rituals.", progress = "Another name for the list.", completion = "This can be the only end for traitors to Maldraxxus.", objectives = "Slay Fa'zinge on the Exoramas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63678] = { id = 63678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akarek Avenged", description = "The last of those traitors involved in taking down Margrave Akarek are dead. \n\nIt will not bring our Margrave back, but I am still pleased.\n\nMy Baroness wished for us to inform Margrave Sin'dane that the job was done before departing for Ardenweald.", completion = "Traitors will not be tolerated.", objectives = "Meet with Margrave Sin'Dane in the Exoramas in the House of Rituals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63679] = { id = 63679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magical Mystery Tour!", description = "<Lady Moonberry's voice rises from the scroll.>\n\n{name}! It seems Huln got into some trouble. And--well--it's complicated. We could really use your help in Revendreth! Please meet me at Dominance Keep.\n\nSee you soon!", completion = "I'm glad you could get here so quickly! We've run into a little bit of a hiccup.", objectives = "Find Lady Moonberry in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63680] = { id = 63680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out On the Edge", description = "It sounds like Huln was taken elsewhere, and by the Stonewright herself!\n\nWe should look for signs she came through the area. Hopefully that will lead us to Huln!", completion = "We found Huln and conveniently he was with just the person we need to help with the ritual!\n\nI love it when things work out for everyone, don't you?", objectives = "Track down Huln Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63681] = { id = 63681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to The Heart", description = "We should hurry back to Ardenweald!\n\nYou go on ahead and find Ysera. I'll escort the Stonewright there and make sure Huln gets back.", completion = "I am glad to see you again. We do not seem to have much time.", objectives = "Return to Ysera in front of the Heart of the Forest in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63682] = { id = 63682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of Elune", description = "We have done as much as we can with the time we had.\n\nNow we must lend our power to Thiernax and the others, and hope Tyrande survives.", completion = "It has been so long...", objectives = "Assist with the ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63683] = { id = 63683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winter's Sigil", description = "My sister... After all this time... She did not abandon me...\n\n<The barest hint of a smile graces the Winter Queen's face before it is gone. She turns her attention to you with the weight of eons.>\n\nAttend me, {name}. Take my sister's tear, and come to the Heart of the Forest.", progress = "Well done.", completion = "<Ysera sighs, relieved.>\n\nSuch peace has returned to Ardenweald and to those who dwell within. My dear friend has been saved. I do not know what comes next, but I have hope.\n\nThis could not have been done without your help, {name}. Thank you.", objectives = "Bring the Sisters' Tear to Ysera at the Heart of the Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63684] = { id = 63684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feral Shadehound", description = "<The runed armor husk pulses with power and seems to struggle for its freedom.\n\nRelease your feral shadehound and bind it to you.>", objectives = "Summon and bind your Feral Shadehound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63685] = { id = 63685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cryptkeeper Kassir's Best Friend", objectives = "{name}, you must forgive me another expression of my gratitude for being included in the Ember Court.\n\nIt has been the honor of my existence, and I am humbled to have played any small part in our prince's success there.\n\nPlease, do not hesitate to call on me if I can ever be of service, my most dear friend.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63686] = { id = 63686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baroness Vashj's Best Friend", objectives = "<Baroness Vashj smiles at you.>\n\n{name}, you have proven to be a welcome diversion from my current endeavors.\n\nI do not regret my skepticism when you first approached me regarding your Ember Court, but I am pleased you have proven them to be unnecessary.\n\nYou and Prince Renathal hold court well. And I am pleased to have spent more time with you.\n\nUntil the next court, my little {name}.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63687] = { id = 63687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lady Moonberry's Best Friend", objectives = "<Lady Moonberry stifles a laugh.>\n\n{name}! I was just telling Goji about our very first Ember Court together. Do you remember? I made the illusions and tried to hit Prince Renathal with my very own-- well, I don't need to tell you again. You were there!\n\nOh, we are kindred spirits, you and I...", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63688] = { id = 63688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mikanikos's Best Friend", objectives = "I like you, {name}.\n\nStrong {name}.\nClever {name}.\nAdventurous {name}.\n\nLike Bron, but smaller... Also better?\n\n\n\nYes, better!\n\n{name} best friend.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63689] = { id = 63689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Countess's Best Friend", objectives = "Redelav Tower basks in the joy of your every footstep here, {name}.\n\nI wish you were able to visit more often, but it is always so with best friends. Do you not agree?\n\n\n\nI have nothing to ask of you today, my dear. I covet your friendship alone.\n\nI trust you appreciate how rare it is to find true, genuine friendship among the lemmings of court.\n\nBut of course you do. You are the host of the finest court in all of Revendreth!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63690] = { id = 63690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alexandros Mograine's Best Friend", objectives = "It has been an honor to fight alongside you, {name}. Perhaps an even greater honor to work alongside you to unite Revendreth.\n\nUntil our time here shall pass, you will always be my brother in arms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63691] = { id = 63691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunt-Captain Korayn's Best Friend", objectives = "<Hunt-Captain Korayn sheathes her weapon with a smile.>\n\nAh, I can finally let down my guard. {name} is here!\n\nNothing bad shall befall us while the mighty Maw Walker walks among us. Even the gorm have learned to tremble at his name.\n\n{name}, our bond has grown through the many battles and courts we have conquered together.\n\nWherever the hunt takes us next, I hope we travel together.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63692] = { id = 63692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Polemarch Adrestes's Best Friend", objectives = "<Polemarch Adrestes stifles a laugh, unaccustomed to its unfamiliar sensation.>\n\n{name}, I was just daydreaming about the first time you invited me to the Ember Court. Do you remember?\n\nI attempted to pass off the responsibility to one better suited for the challenge, but Chyrus thought it would be good for me to grow.\n\nAnd he was right! What accomplishments we have made together... and even a bit of fun.\n\n\n\nYou have bettered me in many ways, my dear friend. Thank you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63693] = { id = 63693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rendle and Cudgelface's Best Friend", objectives = "Me and Rendle was just talking about you, {name}.\n\nHe's been telling all the dredgers dat you're HIS best friend, but I know you're MY best friend. And Rendle's always been my best friend too. So that's all really confusing me.\n\nI says we all be best friends together, yeah?\n\nAnd our friendship is made of strong muck. Best friends forever, I say. BFFs, I calls it.\n\nAnd BFFs always helps each others outta jams. You just let ol' Rendle and me know wheres we needed!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63694] = { id = 63694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Choofa's Best Friend", objectives = "It's official, {name}. Rury, Slanknen, Awool, me -- the whole crew, we've been chatting about our best friend, YOU! And we think you're ready to join.\n\nSo welcome to the crew, best friend! Let's have some fun!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63695] = { id = 63695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Droman Aliothe's Best Friend", objectives = "I have seen many things in my time, {name}. But after so many Ember Courts, I can confidently say that I have not witnessed anything, or anyone, quite like you.\n\nYou and your prince have asked me to ponder both my purpose and my destiny. I do not know how this adventure that we embark upon will ultimately end, but if I should fall, I would hope that I shall fall by your side.\n\nCall upon me whenever you have need of me.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63696] = { id = 63696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grandmaster Vole's Best Friend", objectives = "I've got a real eye for talent. I said it to myself the first time I saw you walking up to the arena, \"This kid's going places!\"\n\nAnd here I am, going there with you.\n\n<Grandmaster Vole flashes a genuine smile as he relaxes for a moment.>\n\nI owe you one, kid.\n\nYou know, despite what you may think, not a lot of quality friend material comes shuffling through here.\n\nAny future bookings you need are on the house. I've always got time for my best friend.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63697] = { id = 63697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleia and Pelagos's Best Friend", objectives = "We have been on quite a journey together, {name}. Although we are not soulbinds, but I feel that we are bound in a different way.\n\nBonded together in purpose, in goal, in friendship.\n\n\n\nWhatever dangers we face as we confront the Jailer, we face together.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63698] = { id = 63698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plague Deviser Marileth's Best Friend", objectives = "My wonderful, glorious, exceptional, intelligent, witty, creative, resilient, viscous apprentice {name}!\n\nI am most pleased to say that you have earned a promotion! I'm honestly not sure what title is above apprentice... none of my apprentices has ever made it this far before.\n\nYour first task as my new best-friend apprentice is to determine a suitably respectable title your new position!\n\nCongratulations! You report directly to Kevin now.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63699] = { id = 63699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sika's Best Friend", objectives = "Thank {name}. Show Sika have many friends.\n\n{name} is best friend. Show Sika rest and party. Show Sika kindness.\n\nSika always help {name}.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63700] = { id = 63700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stonehead's Best Friend", objectives = "Best bud!\n\nYou remember papers you give me lots of times? Sybille help me learn read them!\n\nYou know papers say I can go party a lot? Reading is fun! Reading leads to party!\n\nStonehead always party with best bud!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63703] = { id = 63703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vault of Secrets", description = "You've helped us regain a semblance of order, Maw Walker, but the outlook is dire.\n\nThe Jailer's forces have launched an all-out assault upon the ruins of our vault at the outer reaches of Korthia. Clearly the Banished One seeks something of value inside.\n\nThe vault's defenses activate when the structure is threatened, so getting inside won't be easy. But we must recover whatever the Jailer is seeking before his Mawsworn do.\n\nI've enlisted the aid of a necrolord who can help open the vault.", completion = "We have our smith. Now we must move forward with the plan.", objectives = "Meet with Tal-Galan outside of Scholar's Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63704] = { id = 63704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance for Korthia", description = "While opening the vault is our priority, I  must ask a favor.\n\nWhen Korthia was pulled into the Maw, my people were terrified. We fled to the area you see before you, a place of peace called the Scholar's Den.\n\nThe Mawsworn soon descended upon us. Most of my kind were slaughtered. Others were taken captive.\n\nIf I could claim vengeance myself, I would. But I... I am ill-equipped for battle. Not like you.\n\nPlease. Show these monsters that their defilement of Korthia will not stand!", completion = "Vengeance will not bring back the fallen, but it gives those of us who survived a measure of satisfaction.", objectives = "Slay 15 Mawsworn in Scholar's Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63705] = { id = 63705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Knowledge Keepers", description = "Our vault was built to store countless secrets and artifacts. Even if we gain entrance, we can't be certain of what the Jailer is looking for.\n\nCertain attendants are given the title of record keeper. They track items stored in the vault, and are known for their utmost discretion.\n\nA number of keepers have been taken captive by the Mawsworn and are being tortured for information.\n\nSave the record keepers, {name}. They can help us determine what the Banished One seeks.", completion = "I am relieved to see more of my people freed from the Jailer's grasp.\n\nNow we must determine what he's looking for.", objectives = "Rescue 5 record keepers from Scholar's Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63706] = { id = 63706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let the Anima Flow", description = "Tal-Galan briefed me on the situation and explained the vault's workings. As well as any scholarly type could, at least.\n\nFirst we need to ensure the vault is getting power. They use underground conduits to feed it anima.\n\nThe attendant says that one of these conduits is tucked away in a cave in Scholar's Den.\n\nYou get me there and I'll find a way to fix it. Just watch my back while I figure out how these Korthian devices work.", completion = "After the drought the Shadowlands suffered, I'll never take flowing anima for granted again.", objectives = "Help Bonesmith Heirmir repair the Anima Conduit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63708] = { id = 63708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phantasmagoria", description = "<The strange mote of otherworldly energy glows with an erratic rhythm. \n\nVe'nari may find it of interest.>", completion = "How beautiful. That this Phantasma is able to exist outside of the tower at all is unbelievable. Something is most curious about it's nature...further study is needed.", objectives = "Bring the Warped Phantasma to Ve'nari at Ve'nari's Refuge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63709] = { id = 63709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Vault", description = "What fortune! You rescued the record keepers before the Mawsworn could steal their knowledge of the vault's relics.\n\nBut their records are fragmented. Incomplete. I pray there's enough left to learn the truth.\n\nI will attempt to coalesce the knowledge that remains into a message. If the Purpose wills it, we will learn what the Jailer wants and to whom this item originally belonged.\n\nI must focus for a moment. Let me know when you are ready to begin.", progress = "Are you ready to begin?", completion = "We know what the Jailer wants.\n\nNow we must reach the vault before his forces acquire it.", objectives = "Examine the recovered recordings with Tal-Galan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63710] = { id = 63710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Anima Trail", description = "So the Jailer seeks the Primus's sigil. We must beat the Mawsworn to it. To open the vault, we need to power it with anima.\n\nYou helped the Bonesmith repair the first conduit. The trail of anima in front of us leads to the next. \n\nIf we can activate it, then there should be enough anima flowing into Korthia to get us inside the vault.\n\nCome, we must make haste!", completion = "A chasm!\n\nWe will need a way to get across to the next anima conduit.", objectives = "Follow the anima trail to the next conduit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63711] = { id = 63711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bone Tools", description = "So the device we need to open this vault is stuck on a floating island, eh?\n\nNot a problem.\n\nI see plenty of sturdy creatures around here. Like I always say, no bone goes to waste!\n\nBring me a pile of their bones. I'll use them to craft hookshot points for us to use to grapple over there.", progress = "Remember, I just need the bones. Flesh only gets in the way.", completion = "Yes, this will do. Think I'll save one to show the other smiths back home.", objectives = "Salvage 50 anima-infused bones from wildlife", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63712] = { id = 63712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Records", description = "Some of the record keepers fled to this mountain when Korthia was pulled into the Maw.\n\nI see no sign of them, but they may have left records behind. \n\nTake this beacon. I fashioned it using information from the previous record keepers you rescued.\n\nIt will lead you to any intact records that are on this mountain.", progress = "Have you recovered the records?", completion = "Excellent. I should be able to extract the Primus's message from these records.", objectives = "Use the Matrix Beacon to recover 3 Lost Recordings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63713] = { id = 63713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hooking Over", description = "I've made some solid hookshots and grapple points. Don't worry--if they hold my weight, they'll hold yours!\n\nThey can get us across the chasm to the next anima conduit.\n\nI'll go on ahead and wait for you. No telling what might be lurking over there.\n\nThe sooner we get the anima conduit working, the sooner we get into the vault and claim the Primus's sigil.", completion = "What a ride! Keep that hookshot.\n\nJust be careful using it. That thing will chew through any normal grapple points.", objectives = "Travel to the floating island with a hookshot, then repair the anima conduit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63714] = { id = 63714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Vault", description = "Thanks to the Bonesmith's repairs of both conduits, anima should now be flowing to the vault. That gives us a chance to get inside--assuming we can reach it.\n\nOur Maldraxxi allies have wrangled transportation to get us to and from the vault. I suggest we make haste.\n\nIf the Jailer's minions obtain the sigil of the Primus before we do, it won't just be Korthia that suffers. All the Shadowlands may be forfeit.\n\nLet's go, Maw Walker. Our forces will be awaiting us.", completion = "Tal-Galan informed me of the situation.\n\nWe must get you into that vault.", objectives = "Take a Flayedwing Transporter to the Vault of Secrets", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63717] = { id = 63717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defending the Vault", description = "To reach the vault, we'll need to carve a path through the attacking Mawsworn.\n\nThe covenants are doing their best to drive off these monstrosities, but our allies can't hold out forever. The Mawsworn are intent on reaching the prize before you.\n\nWe could use your help fighting against the Jailer's forces, Maw Walker.\n\nPurpose guide us all.", progress = "Purpose guide your blade!", completion = "Good work fighting those Mawsworn.\n\nWe'll take it from here, {name}.", objectives = "Help Protector Kah-Rev defeat the invading Mawsworn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63718] = { id = 63718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Theotar's Egg", progress = "Like true love, my egg is always within sight but often out of reach...", completion = "You found it! I am most impressed, my friend.\n\nNow do I owe you a kiss or am I mixing up my Azerothian holidays again?" }
quests[63719] = { id = 63719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temel's Egg", progress = "I hid my egg where I keep all of our important party supplies...", completion = "Aw, I made it too easy for you, didn't I?" }
quests[63720] = { id = 63720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prince Renathal's Egg", progress = "My egg is the center of attention, as I hope to be...", completion = "I must admit, I would have never thought to play hide and seek with an egg... What a creative world you come from!" }
quests[63721] = { id = 63721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Garridan's Egg", progress = "I always say, keep your friends close and your eggs closer...", completion = "<Lord Garridan leans in and whispers.>\n\nI ensured that mine would be easy to find so that the guests feel smart. Flattery takes many forms." }
quests[63722] = { id = 63722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keepers of Korthia", description = "We've barely held out against the Jailer's forces. Now that you're here, we can finally make some progress.\n\nI know your priority is to enter the vault, but our record keepers must also be recovered. \n\nThey are the authorities about everything kept in the vault. We can't let the Jailer learn what they know.", completion = "A pity all three keepers did not survive. Good work tracking down the two that did.", objectives = "Rescue 3 record keepers around the Vault of Secrets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63725] = { id = 63725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Vault", description = "The destruction here is... overwhelming.\n\n<Tal-Galan quietly utters a prayer.>\n\nAnima flows into what remains of the vault. We should now be able to enter.\n\nOnce inside, I will work on recovering the Primus's sigil. \n\nPlease show reverence within the vault. It is a sacred place that few are allowed to see.\n\nEven the prophecies did not foretell that a living mortal would gaze upon the secrets within.", completion = "The Primus's sigil! Hmm... I sense a familiar magic upon it.\n\nYes. All those things I saw through your eyes from Torghast...", objectives = "Recover the Primus's Sigil within the vault of Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63726] = { id = 63726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untangling the Sigil", description = "The Primus's sigil is bound together with the magic of memory. It reminds me of something you have encountered before.\n\nYou made an ally of the Runecarver, that poor soul trapped in the bowels of Torghast. He took those memories you found and helped you forge them into weapons and armor.\n\nPerhaps he can separate the sigil from this tangle of memories.\n\nIt's our best chance to secure the sigil. But the way will be perilous.", completion = "We are free. There is still hope to fight back against Zovaal.", objectives = "Speak with Bolvar to discuss what to do with the sigil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63727] = { id = 63727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Primus Returns", description = "The Jailer has four of the five sigils required for what he is planning.\n\nHe is a fool for allowing us to live. His desire to see us bend to his will shall be his undoing.\n\nAll is not lost, if you are willing to put in the work. There is still something that can be done.\n\nCome. I will meet with the rest of your forces and formulate our next attack.", completion = "We can dwell on our past mistakes when this is over. For now, we must move forward.\n\nYou aided me during my imprisonment as the Runecarver. Take this as a token of my gratitude.", objectives = "Meet with the Primus within Keeper's Respite to form a new plan of attack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63728] = { id = 63728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Amid Houses", description = "I have dreamed that Tyrande Whisperwind is crucial to the survival of Ardenweald.\n\nThe night fae have been searching for others like her who were once Night Warriors. We have recruited an ancient ally of Azeroth, Huln Highmountain, in order to look for them.\n\nElune's power is too much for any mortal to contain--even Tyrande. I do not know how much longer she can hold on.\n\nAllow me to explain further, then you must hurry to meet Huln in Maldraxxus.", progress = "Ardenweald appreciates your help.", completion = "Word of your deeds has spread across the Shadowlands.\n\nI know together we will be able to find this Night Warrior swiftly.", objectives = "Speak with Ysera to learn more, then find Huln Highmountain in the Sepulcher of Knowledge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63731] = { id = 63731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Researching Korthian Relics", description = "<You find a torn book regarding relics that were being kept within Korthia.\n\nA name written within its pages begins to glow: \"Roh-Suir.\"\n\nThe book spins in your hand and points in a direction while Roh-Suir's name pulses.\n\nPerhaps this Roh-Suir could help you discover more about the relics you've found.>", completion = "Relics? Research? We have much more urgent matters at hand!", objectives = "Find Scholar Roh-Suir to learn more about relics.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63732] = { id = 63732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Interrupt the Interrogations", description = "Shhh... quietly!\n\nThe invaders will kill me if they find me here, just as they have killed so many others!\n\n<Roh-Suir points frantically in the direction of the Mawsworn.>\n\nThey're torturing the Archivist!\n\nYou must find a way to rescue her. We cannot allow the Mawsworn to learn all that she knows!", progress = "There is no hope until and unless Archivist Roh-Senara is safe.", completion = "What did we do to deserve such cruelty?", objectives = "Rescue Archivist Roh-Senara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63733] = { id = 63733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carving Out a Path", description = "While I abhor violence and prefer a reasoned response to conflict, there is no alternative here.\n\nIn order for Roh-Suir and I to escape safely, you must deliver a decisive strike to the Mawsworn who have invaded Seeker's Quorum.\n\nCarve out a path so that we may escape.", progress = "Attacking the Mawsworn is risky, but necessary. I pray they did not follow us.", completion = "You bought us the moment we needed to make our escape.", objectives = "Defeat 15 Mawsworn invaders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63734] = { id = 63734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sundered Staff", description = "I have no choice but to trust you with the secrets of the Lodestaff.\n\nIn the right hands, such as those of a trained Archivist, the staff can locate influential relics from the afterlives of the Shadowlands.\n\nIt was split into three segments to ensure that it would not fall into the wrong hands. The invaders have found the pieces, but they are yet not aware of their significance.\n\nRecover the pieces of the staff. Each segment is held by a different member of the Mawsworn.", progress = "Were you able to recover all three segments of the Lodestaff?", completion = "I cannot fully describe the relief I feel now that we have the Lodestaff.", objectives = "Recover the three segments of the Lodestaff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63735] = { id = 63735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recover the Research", description = "Though the circumstances are grim, we cannot neglect the Purpose.\n\nOn the bodies of the attendants in the Seeker's Quorum, you will find scrolls detailing our ongoing research. What is written on each of these scrolls represents efforts equal to many of your lifetimes.\n\nRetrieve them, before they are destroyed and lost forever.", objectives = "Recover 6 Scholars' Research Scrolls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63736] = { id = 63736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Infusion of Anima", description = "Normally we would infuse the Lodestaff with energy from the Netherstar, another relic of note.\n\nRegrettably, that is not an option. But, in a pinch, anima is an acceptable substitute.\n\nTake the Lodestaff. Brandish it near recently slain devourers in the estuary below us.\n\nThe staff should draw in and absorb their anima.", completion = "The Lodestaff is humming with vibrant energy! The anima worked better than I could have hoped.", objectives = "Infuse the Lodestaff with anima.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63737] = { id = 63737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding One's True Purpose", description = "All our efforts have led us here.\n\nWith the combined wisdom of the Archivists, and a little help from a {race} {class}, we will attune the Lodestaff to the relics that we seek.\n\nShould we succeed, we will have what we need to re-establish the Archive.\n\nOur sacred work can then continue.", progress = "Is it over? Was the attuning a success?", completion = "So much has been taken from us. And yet, due to Roh-Senara's sacrifice, there is hope.", objectives = "Participate in the ritual to attune the Lodestaff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63738] = { id = 63738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Establishing the Archive", description = "I will head to Keeper's Respite, where there is some small semblance of safety.\n\nThere, we will establish a new archive.\n\nMeet me there when you are able.\n\nI hope we can count on you again. We will have need of your assistance there in the future.", completion = "It is hard to imagine how I will continue without the Archivist.", objectives = "Meet Scholar Roh-Suir at Keeper's Respite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63739] = { id = 63739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hope Ascending", description = "There is one final thing we must do.\n\nMeet us atop the peak of Hope's Ascent.", completion = "I was beginning to worry that you had given up on our cause.", objectives = "Meet Archivist Roh-Senara and Scholar Roh-Suir near the top of Hope's Ascent.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63740] = { id = 63740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consulting the Experts", description = "We can restore the functions of the Lodestaff, but it will require the wisdom of the Archivists.\n\nNot just me, but the Archivists who have come before. They were laid to rest near here. Given the scale of the destruction of Korthia and the likely possibility that this destruction will continue, this may be our last chance to visit their memorials before they are irrevocably ruined.\n\nVisit the Archivists' memorials. Take Roh-Suir with you, so that he may take note of their messages before they are lost.", progress = "Do not fear the Archivists of old. They are here to help.", completion = "I trust you and Scholar Roh-Suir learned from the Archivists.", objectives = "Commune with the Archivists' memorials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63751] = { id = 63751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Terrible Power", description = "This strange shard pulses in your hand. An aura of dread radiates forth from it like a chill wind, sending a shiver down your spine. Perhaps the Primus could tell you more about this... if you could find him." }
quests[63753] = { id = 63753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Centurions March!", description = "Three of our Centurions have broken through the side gate. They need additional anima to continue their assault.\n\nSeveral of my assistants tried to deliver anima to them, but failed. Please get recover the anima and assist the Centurions in the attack.", progress = "Have the Centurions succeeded?", completion = "Quite extraordinary work Maw Walker!", objectives = "Collect 5 Anima Motes to empower and assist the Centurion in combat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63754] = { id = 63754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Caged Bird", description = "Remain quiet. We must not attract attention.\n\nMany of my sisters have already been lost. It will soon be my turn to perish in that witch's vile ritual.\n\nRelease me from this cage and I can see us both to safety. Keeper Odyn must be warned of this foul betrayal!\n\nThe Mawsworn called Kjellrun holds the seal that can free me. You can find her gloating in the nearby hall.", progress = "This is no fate for a Val'kyr!", completion = "I will tell the tale of your noble deeds, {name}. Your actions this day will be remembered.", objectives = "Acquire the Helwrought Seal from Kjellrun and release Danica from her captivity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63755] = { id = 63755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Matter of Urgency", description = "Maw Walker, there is a matter of urgency that has not been addressed.\n\nOur Fatescribe is missing. They have not found their way here. They would have been in Seeker's Quorum before...\n\n<Pathscribe Roh-Vess pauses.>\n\nCan you look for the Fatescribe? Many attendants used the caves near the ruins to hide from the mawsworn.", completion = "You are searching for the Fatescribe too? I must find him. I cannot fail.", objectives = "Search for the Fatescribe of Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63756] = { id = 63756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescued from Torment", description = "The Mawsworn are not only killing those they find in the Seeker's Quorum. They are interrogating the survivors.\n\nWe should help save those we can. It's possible one of them might have seen the Fatescribe.", completion = "I struggle to believe that not a single attendant has any information on where the Fatescribe might be.", objectives = "Rescue 6 Tortured Attendants in Seeker's Quorum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63757] = { id = 63757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looting the Looters", description = "<The Mawsworn was carrying a Korthian artifact.\n\nIt's unclear what the enemy wants with such relics, but you suspect the attendants in Keeper's Respite would want to see them returned.>", completion = "Now this is special. This implement is used by the Fatescribe in his work.", objectives = "Retrieve 4 Korthian Artifacts from the Mawsworn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63758] = { id = 63758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Place You Look", description = "I came here hoping to locate the Fatescribe or something to help me find him.\n\nEvidence shows he was here and survived a Mawsworn attack. The only other place I haven't looked is a meditation chamber on the opposite side of the ruins.\n\nIt's too dangerous for me to head back into the Seeker's Quorum alone. Could you help me?\n\nI must find the Fatescribe. It's a matter of great importance.", completion = "Mad ramblings and incense. Weak clues, but they're all we have.\n\nWe need to search the Sanctuary of Guidance.", objectives = "Search the Seeker's Quorum for the missing Fatescribe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63759] = { id = 63759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redirect the Search", description = "I believe the Fatescribe was headed to the Sanctuary of Guidance. A holy place for the attendants of Korthia.\n\nFortunately, because you seem to be in the habit of picking up every piece of trash you find, we have the Fatescribe's Implement!\n\nI'm sure that will prove useful in locating him. But first, on to the Sanctuary.", completion = "{name}! At last! \n\nYou know that I cannot do this without you.", objectives = "Meet Caretaker Kah-Than at the entrance to the Sanctuary of Guidance in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63760] = { id = 63760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echoes of Fate", description = "The devourers have swarmed this place, but our focus must remain on finding the Fatescribe.\n\nAttendants who worshipped here would leave offerings of anima at the shrines.\n\nThe implement you found will resonate if the Fatescribe has been nearby. With any luck, it will give us insight into where he has gone.", completion = "Using an illusion to hide.\n\nCan you imagine anything so clever?", objectives = "Resonate the Fatescribe's Implement at the shrines in the Sanctuary of Guidance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63761] = { id = 63761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revenge Delayed", description = "<The Korthian protector is gravely wounded and struggles to speak.>\n\nDevourers... swarmed the sanctuary. Too few of us...\n\nMy duty... incomplete.\n\nThe Purpose... I...\n\n<The protector's voice fades.>", completion = "<You have completed the protector's task.>", objectives = "Kill 10 Devourers in the Sanctuary of Guidance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63762] = { id = 63762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under the Illusion", description = "The Fatescribe has collected the necessary items to create an illusion in this chamber. Fortunately, we can use his own implement to dispel it and reveal him.\n\nHe will be grateful to see a friendly face, I'm sure.\n\nI must say, you've proven to be incredibly helpful in this task. I truly couldn't have done it without you.", objectives = "Use the Fatescribe's Implement to dispel the illusion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63763] = { id = 63763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Could Be Anyone", description = "<The still-warm head of the dreadlord Azodius grimaces at you.\n\nThe attendants at Keeper's Respite should be told of the Fatescribe's abduction.\n\nNo doubt Highlord Fordragon will want to hear of this unexpected threat.>", completion = "News of the nathrezim infiltrating Korthia is deeply troubling.\n\nHow long have they been here? What is their goal?", objectives = "Take the head of Azodius to Bolvar Fordragon in Keeper's Respite.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63764] = { id = 63764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claim the Sky", description = "I mourn the loss of my sisters and desire nothing more than to avenge them. Yet I know that I am no match for the witch's magics or her army of Mawsworn.\n\nWe must let wisdom guide us and fly from here. \n\nThough I am weak from my captivity, I have the strength to bear you from this place.\n\nLet us go, friend.", completion = "Welcome to Skyhold, {name}.", objectives = "Fly with Danica to Odyn's halls in Skyhold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63765] = { id = 63765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unseen Hero of the Party", progress = "Oooh, this book looks long, I bet it is incredibly important.", completion = "This is what you had to do each week? I'll take care of this now, I won't let you down!" }
quests[63771] = { id = 63771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fate's Reminder", description = "Fatescribe Roh-Tahl awaits you within Oribos, should you ever wish to change the course of fate.\n\nYou may speak with him at your leisure.", completion = "You return, mortal.\n\nDo you wish to change your fate?", objectives = "Meet Fatescribe Roh-Tahl in Oribos if you wish to enter the Threads of Fate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63772] = { id = 63772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waiting in the Wings", description = "Kyrian forces have arrived to assist in the assault. They have secured our flank and will lay siege to the south gate of Perdition Hold. \n\nReport to Artemede and assist the Kyrians however you can!", completion = "Your presence here gives us renewed hope.", objectives = "Assist Artemede and the Kyrian forces outside the southern gate of Perdition Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63773] = { id = 63773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You and What Army", description = "The Jailer has dispatched a force of elite troops to strike our rear lines. Their attack threatens our whole assault!  \n\nI need you and one other soldier to eliminate these enemies. A volunteer from each of the five houses of Maldraxxus has requested to assist you, {name}.\n\nPick one and give them the honor of serving alongside you.", completion = "Victory will be ours, Maw Walker!", objectives = "Select a champion and Eliminate 3 Mawchained Rampagers and 5 Mawchained Demolishers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63774] = { id = 63774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Embarrassment of Corpses", progress = "Find the disembodied souls and bring them to my stitchers!", completion = "The work of a Maldraxxian soldier is never complete!", objectives = "Deliver 4 Disembodied Souls to Front-Line Stitchers who will craft them new bodies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63775] = { id = 63775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cryptograms and Keys", description = "The repositories of knowledge within Korthia have layers of security--for very good reasons.\n\nEach vault requires cryptographs in order to decode and disable the barriers. They are, for lack of a better term, the keys to every secret.\n\nSearch outside the Vault for cryptographs stolen by the Mawsworn and return them to me. I will keep them, and the secrets they protect, safe.", progress = "We cannot allow the Jailer to raid the Vaults of Korthia.", completion = "I am deeply grateful for your service in keeping our secrets from the Jailer.", objectives = "Retrieve 6 Stolen Cryptographs from outside the Vault and Seeker's Quorum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63776] = { id = 63776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Observational Records", description = "Greetings, Maw Walker, a moment of your time?\n\nAs you no doubt know, my cartel has quietly spread observational devices all across Korthia. But that data is no good to us if it is not retrieved. Which is where you come in.\n\nThe Scholar's Den records should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb.\n\nBe sure to check in the caverns below ground, as well!\n\nBring those data to me, and I will reward you handsomely.", progress = "Have you retrieved the observational records from the Scholar's Den?", completion = "The Scholar's Den must have been a much different place before the Jailer's chains destroyed it. It is hardly a refuge for intellectual pursuits now.\n\nThis information is extremely valuable to us. And here is your reward, as promised.", objectives = "Collect 5 Observational Records from the Scholar's Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63777] = { id = 63777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealed Secrets", description = "Ah, Korthia. What secrets will be revealed?\n\nMy associates have been hard at work, seeking to discover and procure various small items of interest throughout this broken land. Nothing of great importance, I assure you.\n\nThey have secured those items in designated drop boxes, and those now await pickup in the Scholar's Den. Don't worry: they are locked with an impenetrable seal to protect both the contents and the deliverer.\n\nBring those sealed containers to me, and I will reward you handsomely.", progress = "Do you have the sealed containers?", completion = "Wonderful! You brought everything that I asked for.\n\nAgain, do not worry about the contents of these boxes. They pose no threat to you.\n\nHere is the reward I promised.", objectives = "Retrieve 5 Sealed Containers from the Scholar's Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63778] = { id = 63778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Move Forward", description = "It breaks my heart to see another land so utterly obliterated. I can imagine how beautiful Korthia must have been, once.\n\nBut we must not wallow in what we've lost. Like Ara'lon taught me: we don't have to stand still.\n\nWe can choose to fight.\n\nYou can help by taking anima back from those Mawsworn. We can put it to use, building up our own forces and defenses.", progress = "I look forward to a time when we aren't always fighting for survival.", completion = "Thank you, my friend.\n\nEvery bit of anima we collect gives me hope that we can heal the Shadowlands. One day, we will be whole again.", objectives = "Collect 8 Plundered Anima from Scholar's Den in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63779] = { id = 63779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Semblance of Normalcy", progress = "How are you? I have heard the Sanctuary of Guidance is overrun with devourers.", completion = "How wonderful. We will return these to the attendants so they may once again participate in their rituals. It's important to do activities that bring us peace.", objectives = "Gather 6 Shrine Offerings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63780] = { id = 63780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "See How THEY Like It!", description = "Just thinking about how the Jailer's forces breached Ardenweald makes me so mad! \n\nAnd when I get mad, I get even.\n\nOr rather, I get your help with getting even! Slay those Mawsworn and bring back their emblems to show me how many you killed. \n\nI don't really care where you get them, as long as they come from those Maw jerks!", progress = "Those Mawsworn will get what they deserve!", completion = "So many emblems! That makes me so happy.\n\nEverything will be better when we've gotten the Jailer himself, but this will do nicely for now.\n\nThank you!", objectives = "Collect 12 Mawsworn Emblems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63781] = { id = 63781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mawsworn Battle Plans", description = "Which is more damaging to the enemy, destroying a contingent of their forces or interrupting their communications?\n\nBetter yet, what if that communication allows you to best place your forces to ambush their reinforcements?\n\nI see you understand. There will be a Mawsworn lieutenant, Voxiferus, traveling from the Maw into Korthia, by way of the northern road. Find them, kill them, and bring me the battle plans.", progress = "Have you found and defeated the Lieutenant?", completion = "Again, you survive. You remind me of me. I will review these plans and inform our companions.", objectives = "Retrieve the Mawsworn Battle Plans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63782] = { id = 63782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mawsworn Rituals", description = "The Mawsworn have a myriad of magic users among their forces. Their magic is unknown to us and that makes it deadly.\n\nWe need to learn what they are capable of to properly prepare a defense. My own curiosity about their methods and rituals is secondary.\n\nHunt down these vile casters and bring me their grimoires.", progress = "Knowing your enemy is a powerful weapon.", completion = "The information contained in these is dangerous and vile. But knowing what our enemy can do helps us protect against it.", objectives = "Collect 8 Mawsworn Grimoires.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63783] = { id = 63783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anima Reclamation", description = "Our efforts here need a constant supply of troops, supplies, and anima. The last one is the hardest, for obvious reasons. But I've learned to be resourceful. \n\nNearby there is a plentiful source of anima: the devourers that currently swarm the Sanctuary of Guidance. It's not as easy as beating it out of a soul, but it's just as effective, if you're strong enough. Are you?", progress = "Every drop of anima we reclaim is a potential weapon against the Jailer.", completion = "You can trust me with this anima. I will see it is turned against the Jailer and his forces.", objectives = "Reclaim 8 Devoured Anima from devourers at the Sanctuary of Guidance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63784] = { id = 63784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gold's No Object", completion = "Look at 'em! Drab little buns. They jus' blend in ta the wood work. That's stinkin' useful innit?", objectives = "Retrieve 7 Drab Gromits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63785] = { id = 63785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Continued Efforts: Seeker's Quorum", description = "The onslaught from Zovaal's forces continues to devastate these lands.\n\nWe must send them a message. Show them we will not back down, {name}.\n\nThe might of Ardenweald stands with you.", completion = "Quite the show you put on, {name}.\n\nThat should buy us just enough time to sharpen our blades before our next battle.", objectives = "Repel the Jailer's forces from Seeker's Quorum in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63786] = { id = 63786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweep the Windswept Aerie", description = "The skies over Korthia are a dangerous place.\n\nNot only do the Mawsworn threaten our forces; the native creatures are also openly hostile. We must keep the skies safe for our own winged allies and beasts.\n\nThe source of the native flyers is the Windswept Aerie. Go there and clear the aerie of aggressive creatures.\n\nThen, we shall have aerial supremacy.", completion = "Excellent work, Maw Walker. With the Windswept Aerie under control, our flyers stand a chance of ruling the skies.", objectives = "Travel to the Windswept Aerie and clear the area of hostile creatures.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63787] = { id = 63787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Continued Efforts: Mauler's Outlook", description = "My Eyes tell me that the Mauler's Outlook is near the newly formed road from the Maw into Korthia. It would provide a strategic and tactical advantage.\n\nUnfortunately, the area is overrun with shardhides.\n\nIf we can secure the area, it will provide us with a clear path to the west, as well as a point of observation to monitor the Jailer's forces.", progress = "Has Mauler's Outlook been secured?", completion = "The tactical advantage we now hold is a huge win against the Jailer's Forces. Well done, {name}.", objectives = "Clear Mauler's Outlook of shardhides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63788] = { id = 63788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Continued Efforts: Sanctuary of Guidance", description = "The attendant's home has been destroyed by the Jailer, but we can help them in this trying time.\n\nNearby is the Sanctuary of Guidance. They speak of it with reverence and great sadness. It is a place they go to pray and seek truth. It's currently infested with devourers.\n\nClear out the devourers, so they may once more seek solace in their rituals and prayers.", progress = "Have the devourers been cleared out of the Sanctuary of Guidance?", completion = "Thank you, Maw Walker. I am sure the attendants will feel great relief and joy at being able to return to their holy place.", objectives = "Clear the Sanctuary of Guidance of devourers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63789] = { id = 63789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Continued Efforts: Scholar's Den", description = "We cannot allow the mawsworn a foothold so close to our own encampment. The attendants say they keep this place hidden from eyes, but I will not rest easy while I can see them.\n\nEnter the Scholar's Den and cleanse the Jailer's forces from it.", progress = "Has the Scholar's Den been cleared of mawsworn?", completion = "You have performed admirably in this task, Maw Walker. We thank you for your aid.", objectives = "Clear the mawsworn from the Scholar's Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63790] = { id = 63790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broker's Bounty: Lord Azzorak", description = "A powerful dreadlord named Lord Azzorak is hampering the efforts of the Cartel in Korthia.\n\nAnyone who exterminates this evil will be rewarded. \n\nUse caution. Azzorak is a powerful foe. You may require several allies to slay him.", completion = "Thanks to you, Lord Azzorak will no longer hinder Cartel Xy here in Korthia. \n\nYou have my personal thanks as well, Maw Walker. I see many great things in our future.\n\nPlease accept this reward as a token of our gratitude.", objectives = "Defeat Lord Azzorak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63791] = { id = 63791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broker's Bounty: Valdinar the Curseborn", description = "A spike-armored Mawsworn named Valdinar the Curseborn is hampering the efforts of the Cartel in Korthia.\n\nAnyone who exterminates this evil will be rewarded. \n\nUse caution. Valdinar is a powerful foe. You may require several allies to defeat him.", completion = "Thanks to you, Valdinar the Curseborn will no longer hinder Cartel Xy here in Korthia. \n\nYou have my personal thanks as well, Maw Walker. I see many great things in our future.\n\nPlease accept this reward as a token of our gratitude.", objectives = "Defeat Valdinar the Curseborn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63792] = { id = 63792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broker's Bounty: Nocturnus the Unraveler", description = "A nefarious Maw magus named Nocturnus the Unraveler is hampering the efforts of the Cartel in Korthia.\n\nAnyone who exterminates this evil will be rewarded. \n\nUse caution. Nocturnus is a powerful foe. You may require several allies to defeat him.", progress = "What news do you bring of Nocturnus the Unraveler?", completion = "Thanks to you, Nocturnus the Unraveler will no longer hinder Cartel Xy here in Korthia. \n\nYou have my personal thanks as well, Maw Walker. I see many great things in our future.\n\nPlease accept this reward as a token of our gratitude.", objectives = "Defeat Nocturnus the Unraveler.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63793] = { id = 63793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broker's Bounty: Ensydius the Defiler", description = "A winged Mawsworn named Ensydius the Defiler is hampering the efforts of the Cartel in Korthia.\n\nAnyone who exterminates this evil will be rewarded. \n\nUse caution. Ensydius is a powerful foe. You may require several allies to defeat him.", completion = "Thanks to you, Ensydius the Defiler will no longer hinder Cartel Xy here in Korthia. \n\nYou have my personal thanks as well, Maw Walker. I see many great things in our future.\n\nPlease accept this reward as a token of our gratitude.", objectives = "Defeat Ensydius the Defiler.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63794] = { id = 63794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broker's Bounty: Hungering Behemoth", description = "New lands bring new opportunity. We will provide a quantity of valuables to any interested party in return for a substantial amount of devourer blood, preferably the goliath kind.\n\nFaint-hearted collectors need not bother.\n\nPlease bring this sample to Ta'nasi in Keeper's Respite.", progress = "Have something to trade?", completion = "<Ta'nasi holds the sample up to the sky.>\n\nAn excellent specimen. This will do nicely.\n\nAs promised, here is your reward in trade.", objectives = "Retrieve a Substantial Amount of Devourer Blood from a Hungering Behemoth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63810] = { id = 63810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Birds of a Feather", description = "I have seen many ebon wings in the Maw, but never brilliant golden ones.\n\nNow that the aural sequencers are relaying information reliably, we should discover the source of these feathers.\n\nFollow the trail, Maw Walker. There is a mystery here... and very likely profit.\n\nGold has value where you come from, does it not?", completion = "My heart rejoices to see a noble face in this realm of nightmare.", objectives = "Follow the trail of golden feathers to find what dropped them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63811] = { id = 63811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hate-Hate Relationship", description = "When the first of my sisters went missing, we were concerned. Those sent to find her did not return. Nor did the next.\n\nWhat we have discovered is a dreadful betrayal by someone we once trusted.\n\nCome, we must tell Odyn what we have witnessed in the Maw.\n\nHis wrath will be great.", progress = "I do not fault the messenger, {name}.", completion = "Helya has gone too far!", objectives = "Accompany Danica to the Great Mead Hall and inform Odyn of Helya's actions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63822] = { id = 63822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venthyr Assault" }
quests[63823] = { id = 63823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Night Fae Assault", description = "The Jailer's forces  have been caught off guard by our attack. We shall overrun Perdition Hold and defeat his champions at the Altar of Domination!\n\nWe need your help Maw Walker. Assist our forces on the battlefield!", objectives = "Complete 1 quests in Perdition Hold and the Face of Oblivion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63824] = { id = 63824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kyrian Assault", description = "The Jailer's forces  have been caught off guard by our attack. We shall overrun Perdition Hold and defeat his champions at the Altar of Domination!\n\nYour help is needed Maw Walker. Assist our forces on the battlefield!", objectives = "Complete 1 quests in Perdition Hold and the Face of Oblivion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63827] = { id = 63827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encouraging Words", description = "Our forces have been battling relentlessly for hours. No doubt they grow tired and disheartened.\n\nTake this codex and recite the words within to our troops. Do not be fooled. Though the prose may seem meaningless, it holds immense power.\n\nHearing these words will reinvigorate our exhausted Protectors with hope.", completion = "You have done much to help our forces. Thank you,{name}.", objectives = "Recite the words within the codex to 8 Exhausted Protectors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63828] = { id = 63828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mine's Bigger", description = "The Jailer has deployed a large number of newly forged constructs to oppose our forces. Fortunately, I was completely prepared for this possibility. \n\nI have readied our largest Centurion to repel this threat.\n\nPlease Maw Walker, ride with our Centurion and direct it in combat.", progress = "Have we driven back their constructs?", completion = "The Jailer's forces are unending and our numbers few, but with your help we shall succeed!", objectives = "Use the Centurion Demolisher to eliminate the Jailer's constructs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63829] = { id = 63829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No One Floats Down Here", description = "Now is our chance to free those we had assumed were lost!\n\nMany of our aspirants were seized by the Jailer to make troops for his army. Those that resisted him are locked in the cages that float above us, left there till their souls are broken. \n\nShatter the Chains of Domination and free the Trapped Aspirants from the cages.", completion = "Your actions show the purity of your soul. Artemede and I would fight along side you any day, Maw Walker.", objectives = "8 Trapped Aspirants rescued.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63831] = { id = 63831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fury Given Voice", description = "I will answer this attack upon my val'kyr with relentless fury!\n\nYou have a vital role to play in this, {class}. You will muster the courage that you have demonstrated this day to lure my Eye to battle.\n\nBut first, a simpler task ... the creation of the horn that will summon my wrath. Master Smith Helgar will guide you.", progress = "Where is the horn that you have forged?", completion = "This is well made, {name}.\n\nOf course, every great horn has a name. It is our tradition!", objectives = "Assist Master Smith Helgar at the Forge of Odyn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63833] = { id = 63833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrorizing the Tremaculum", description = "I am certain that my compatriots and generals have more specific tasks they require of you.\n\nBut my request is simple. Our enemies currently surround us on all sides.\n\nPush them back and give us more room to operate.", progress = "Our enemies surround us on all sides. You need not search far.", completion = "We may not see an end to the Jailer's forces now, but all things must eventually end.\n\nEven evil.", objectives = "Kill 30 enemies in the Tremaculum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63834] = { id = 63834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of the Tremaculum", description = "The venthyr of Sinfall do not waste souls, and her stoneborn do not waste armaments.\n\nRetrieve the tools of our enemies so that we may repurpose them for our army.", progress = "Every weapon can be made to serve.", completion = "Few weapons are intrinsically good or evil. That burden lies with those who wield them.", objectives = "Collect 6 Mawsworn Weapons, 6 Ghastly Crowns, and 6 Shade Eyes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63835] = { id = 63835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Party Herald", progress = "You can find Temel on the ramparts near the Curator.", completion = "Ha! I presume the Jailer had never considering planning for a party herald's attack.", objectives = "Help Temel, the Party Herald, throw poison bombs at 50 enemies in the Tremaculum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63836] = { id = 63836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fangcrack's Fan Club", description = "Fangcrack is the strongest dredger I e'er seen! He's incredible!\n\nHe's down there, reaching into dat big Torghast portal, pulling the baddies right out o' their home!\n\nThey don't even know what's happenin' half the time, ha ha!\n\nMe and Cudgelface joined his fan club soon as we got here.\n\nYou want in? You gotta earn your membership same as everyone else: go down there and fight whatever he pulls out of the portal!", progress = "Looking for Fangcrack? Follow the cheering of his fans.", completion = "You also joined Fangcrack's fan club? So did Lady Moonberry.\n\n<Prince Renathal thinks for a moment.>\n\nPerhaps I should reconsider my earlier rejection of Rendle's invitation to join...", objectives = "Kill 12 Torghast enemies pulled out of the portal by Fangcrack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63837] = { id = 63837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tea for Every Occasion", progress = "Tubbins is up on the ramparts with Theotar.", completion = "Tubbins promised to save me a cup for our victory celebration at the Ember Court!", objectives = "Help Tubbins and Gubbins deliver tea to 15 allies in the Tremaculum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63838] = { id = 63838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duelist's Challenge", progress = "Boot the Beaut can throw you up to the ramparts if needed.", completion = "Nadjia single-handedly held off an entire platoon of Mawsworn while the dredgers established our base.\n\nEven General Draven was impressed.", objectives = "Ask Boot the Beaut to throw you to the upper ramparts, then duel the champions of the Mawsworn army.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63839] = { id = 63839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If Even One is Worthy", description = "I have seen firsthand that worthy souls have been unjustly cast into the Maw.\n\nGresit here was almost cast in himself by the Lord Chamberlain's minion. He has more than proven himself under my care.\n\nLook among the souls that the Jailer's filth have deemed \"unworthy\". Inspect each to confirm that they deserve their fate.\n\nEven if we examine every soul in the Tremaculum and find only a single worthy one to bring back to Revendreth, it will still be valuable.", completion = "Even in the depths of the Maw, the Accuser remains focused on saving any soul she can...\n\nHer devotion to Revendreth's true purpose continues to inspire me.", objectives = "Inspect Unworthy Souls in the Tremaculum until you find one that is truly worthy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63840] = { id = 63840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Grow Up So Quickly", description = "I know what you're thinking, but I have these gormlings completely under control!\n\nI picked up a trick or two at the venthyr's Ember Court for suppressing and controlling these troublemakers.\n\nIf you wish to use their power to aid our battle, I will loan you my staff. With it you can choose a gormling that can be ordered to feed on the corpses of our enemies and grow in strength and size.\n\nYou won't need many. Gormling grow quickly.", progress = "If you have lost your gormling, Niya up on the ramparts will have found it.", completion = "I will keep the gorm restrained here until they are needed.", objectives = "Grow a gormling by feeding it corpses and ride it to victory!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63841] = { id = 63841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Skyhunt", description = "Boot the Beaut and the other large dredgers are being hit hard from air assaults.\n\nThe dredgers may not be able to reach them, but the Wild Hunt can reach any prey.\n\nTake my spear and use it to ground the Mawsworn in the sky above the western bridge.\n\nOnce they are grounded, they will be easy to dispatch.\n\nMy trappers will help slow them down for you.", progress = "The Mawsworn flyers appear to be focusing their attention on the western bridge.", completion = "Thank you, {name}. Our biggun dredgers are critical to troop movement in the area.", objectives = "Use Korayn's Spear to pull 8 Mawsworn Skylurkers to the ground and kill them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63842] = { id = 63842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's a Good Trick", description = "These cruel tormentors make me so mad...\n\nThe Jailer's bullies torture good souls sent here unjustly because no one will stand up to them!\n\nWell, I am here now, and I have the perfect plan to make them pay.\n\nWhat do you say? Want to help me turn the tables on these bullies?", progress = "Well, if Lady Moonberry thinks it wise...", completion = "Let it not be said that it was ever boring while Lady Moonberry was present.", objectives = "Shrink 15 enemies and enlarge 4 Mawrats to eat them in the Tremaculum!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63843] = { id = 63843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart and Soul", description = "The Forsworn that serve the Jailer dominate the skies above, but we know their weakness and shall use it against them.\n\nUnder my direction Mikanikos has created a supply of Trueheart Spears for our Protectors. When hit by these spears the Mawsworn will be weakened with their soul laid bare as they face their true self.\n\nCollect the Trueheart Spears and use them to defeat the Mawsworn Myrmidons that fly above us.", progress = "Have the Forsworn been defeated?", completion = "There is great sorrow in this victory, but it had to be done.", objectives = "Collect 6 Trueheart Spears and defeat 6 Mawsworn Myrmidons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63844] = { id = 63844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Chosen Few", description = "I have need of more val'kyr to join Danica in the battle to come. {name}, you are granted the honor of choosing the most worthy.\n\nThe strongest will present themselves in challenge at the Circle of Glory. Fight hard, {class}, and do honor to your weapons.", progress = "Have the worthy been selected?", completion = "Well fought. Kolfinna, Dryfinna, and Aeskir have risen to the challenge and await you in Odyn's hall.", objectives = "Go to the Circle of Glory and fight the val'kyr to determine which are most worthy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63845] = { id = 63845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of Odyn", description = "The horn has been forged and the worthy have been selected.\n\nNow, {name}, we have only to bind my chosen val'kyr to the horn and infuse them with my power that they may strike with my fury.\n\nCome, bear witness.", progress = "Yes? Did you have a question?", completion = "It is done. Danica and her sisters are infused with my power and wield my wrath.", objectives = "Bear witness to the empowerment of the chosen val'kyr and the binding of the Ilskahorn", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63846] = { id = 63846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ember Count", description = "Theotar's brilliance is undeniable, but far too many overlook the ingenuity of his dredger helpers, Gubbins and Tubbins.\n\nLook to that ridge beyond us. The Jailer's forges over there are spewing out Soulsteel Embers.\n\nWe could accomplish many things with a mirror made from them...\n\nGubbins has already crafted a special parasol, capable of shielding its wielder from any falling embers.\n\nMeet him by the forges and obtain some of those Soulsteel Embers!", progress = "Have you acquired the embers?", completion = "Charred shards! These will make some very fine mirrors.", objectives = "Slay 4 Enraged Forgeshard and Collect 4 Soulsteel Embers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63848] = { id = 63848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Show of Gratitude", description = "Your presence here fulfils an ancient prophecy, Maw Walker. I am certain you and your allies will save us.\n\nPerhaps I judged your broker friend too harshly. She did escort you to Korthia, after all. \n\nPlease extend our thanks to Ve'nari, and let her know we are happy to answer her questions.\n\nShe... does seem to have quite a number of them.", completion = "A thank-you is polite.\n\nA favor is better.", objectives = "Speak with Ve'nari at Keeper's Respite in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63849] = { id = 63849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hearing Aid", description = "How fortuitous! You just happened to be transferred to a location in which I have a certain... interest. Place the aural sequencers I gave you and I will attempt to establish a functional signal.\n\nSuch a perilous location will require the utmost discretion. You will want to use your ethereal cloak to avoid being seen.", completion = "Perfect. Their secrets will soon be mine.\n\nPardon me. I meant to say \"ours.\"", objectives = "Place the Aural Sequencers in Desmotaeron to help Ve'nari eavesdrop on the inhabitants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63850] = { id = 63850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking - Small Consoles" }
quests[63853] = { id = 63853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill the Flame", description = "Can you see it?  \n\nJust out of the corner of my eye, it's always there... glowing so brightly!\n\nHow is one supposed to relax and enjoy a cup of tea while that reminder of fire and ash is around.\n\nPlease Maw Walker do me a favor... remove it so that we may all enjoy a cup of my favorite blend!", progress = "Have you killed that dreadful creature?", completion = "A sweet reprieve from that creature's dreadful glare.", objectives = "Kill Infernus the Infinite for Theotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63855] = { id = 63855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ease of Passage", description = "Korthia is ripe with opportunity. Look at all of these intriguing objects.\n\nIn anticipation of such wonders, I have come prepared. Let us find a suitable location and establish a more permanent connection between this place and my refuge.\n\nOur work together is not yet finished.", progress = "I'll take my bag now, if you have it.", completion = "A worthwhile trip that has opened so many possibilities.\n\n<Ve'nari digs through the heavy bag and pulls out a few unusual objects.>", objectives = "Establish a connection between Korthia and Ve'nari's Refuge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63856] = { id = 63856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gathering of Covenants", description = "Though the Jailer remains confined to the Maw, his cruelty extends beyond the bounds of his prison.\n\nThankfully, the Archon is recovering from the attack. Though I am told her wound has an... unsettling quality.\n\nThe Eternal Ones and their allies await you and Highlord Fordragon in the Arbiter's chamber. I shall open the way.\n\nWith her voice have I spoken.", completion = "<Bolvar stares in wonder at the sight before him.>", objectives = "Speak to Tal-Inara to enter the Arbiter's chambers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63857] = { id = 63857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voices of the Eternal", description = "<Bolvar peers at the grand figures before him, at the numberless gateways stretching out into the ether.>\n\nThis chamber is... truly wondrous.\n\nYet there is no time to be awestruck. The Honored Voice must begin this meeting at once.", completion = "The Winter Queen must be the Jailer's next target.\n\nWe must do all we can to protect her.\n\nAnd I have a few ideas how we can do that...", objectives = "Listen to the plan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63858] = { id = 63858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Courage of the Soul", description = "In this time of conflict, we are all tested, Maw Walker. It takes great bravery and strength of soul to confront our enemies without fear.\n\nWade into their lines and show them the power of your courage.", completion = "You display the greatest of courage.", objectives = "Eliminate 15 of the Jailer's forces in Cocyrus and Zovaal's Cauldron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63859] = { id = 63859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saved By The Bells", description = "Our stewards are preparing Reinforcement Bells to summon additional Kyrian to aid in our assault. However, the Mawsworn have been attacking the stewards in order to disrupt their efforts. \n\nWe need you to defend our stewards while they complete their work, then ring each bell to call in reinforcements.", completion = "The sounds of those bells strengthens our hearts and gives us the might to win this battle.", objectives = "Defend and ring the Reinforcement Bell West, East, and South.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63860] = { id = 63860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talisman of the Eternal Scholar", description = "<The talisman is dented and spattered with muck. Whoever stashed this here handled it roughly.\n\nArchivist Roh-Suir has a spot for this talisman in the Reliquary of Remembrance.>", completion = "Where... where did you find this?\n\n<The Archivist brings the talisman closer for inspection.>\n\n I haven't seen this in eons. I thought it had been lost.", objectives = "Bring the Damaged Talisman to Archivist Roh-Suir in the Reliquary of Remembrance.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63861] = { id = 63861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beginning the Collection", description = "Let us continue our work by retrieving the most important item of any scholarly study--the lost codex.\n\nIt will take some time, but as we continue our work the pages of this work will continue to grow and flourish, just as Korthia has itself for eons.\n\nAs for its location, it previously resided deep within the underbelly of Korthia itself inside the Cavern of Contemplation to the south.\n\nWe can only hope the Jailer's forces have yet to locate it.", progress = "Have you found the codex? I hope we're not too late.", completion = "Yes, yes. This is it. Magnificent, don't you agree?\n\n<The damp codex catches The Archivist by surprise. He gently runs his hand along the binding, muttering an incantation in a soft, enigmatic tone.>\n\nThat should help preserve it for now, but the incantation won't last. We must get to work.", objectives = "Recover the Codex of Memories for Archivist Roh-Suir in the Reliquary of Remembrance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63863] = { id = 63863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "United In Pride", description = "Despite our competitive differences, Nemea and I work as a team when faced with greater threats. The pride and the phalynx are both fierce fighters upon the battlefield.\n\nWe would both be honored to assist you in the battle that lies ahead.\n\nPlease allow either Andira or Gatamatos to assist you in defeating the Jailer's champions that threaten our forces.", progress = "With those champions defeated our forces can push forward.", completion = "You display the greatest of courage.", objectives = "Defeat Malfestus, Domonous, and Furis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63864] = { id = 63864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dreadful Blend", description = "Gravedust and Stipple Weed is a dreadful flavor combination, and Tubbins made a very large batch of tea with those ingredients.\n\nIt was so horrid that I tossed the entire pot of tea on the fire. It turns out to be very wet, and an excellent extinguisher of flames! \n\nTubbins will haul the entire batch with you. Put it to good use, by tossing it on the Volatile Embersparks around Zovaal's Cauldron.", progress = "Please, I hope you did not drink that.", completion = "Please tell me you did not drink any of that dreadful brew. We deserve only the finest blends for all our efforts here.", objectives = "Extinguish 30 Volatile Embersparks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63867] = { id = 63867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anger Management", description = "I am no musician, though I've spent many an hour enjoying the entertainment in Tazavesh.\n\nGiving this horn a voice will require the harvest of strong emotions.\n\nAnger seethes unrestrained within the damned unfortunates consigned to the River of Souls. Use this siphoning device to drain the rage of these furious shades into your instrument.\n\nThe shrieks of fury that you acquire should allow you to pierce the Maw and reach your allies.\n\nThe tune, I suspect, will not be a popular one.", completion = "The instrument's voice will not be pleasing to most ears, but I believe it will serve its purpose.", objectives = "Use the siphoning device to drain rage from the Furious Shades in the River of Souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63892] = { id = 63892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diviner's Rune Chits", description = "<Inside the pouch is a single rune chit. It rotates and flips as if moved by an unseen hand.\n\nRunes vaguely reminiscent of the Vrykul language are delicately carved into the stone. On the back of the chit is an indication that it is part of a set.>", progress = "Goodness, is that a pouch of rune chits? How many do you have?", completion = "You have acquired a complete set of Diviner's Rune Chits!\n\nThis was one of the first relics that I studied as an acolyte scholar. If you cast the chits, the resulting scatter and orientation will answer any question you ask of them, though it takes experience and a good deal of intuition to interpret their meaning.\n\nI never expected to see a complete set again.", objectives = "Collect 20 rune chits, then bring them to Archivist Roh-Suir in the Reliquary of Remembrance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63895] = { id = 63895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grab Bag", description = "Interesting. Aural sequencers and an ethereal cloak. You hang on to those, {name}. I have a suspicion they will prove useful.\n\nAh, and something special for me as well. If I'm not mistaken--and I so rarely am--this is a projection mechanism. Very handy!\n\nAnd what's this? A transportation device of some kind. We should test it immediately.\n\nBy \"we,\" of course I mean you.", completion = "This projector is certainly useful. A safe landing, I perceive.", objectives = "Test the transportation device from Ve'nari's bag.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63896] = { id = 63896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tears of the Damned", description = "To anchor the instrument to the Maw and make it capable of the effect you seek, it must be imbued with the raw, unfiltered agony endured by the souls trapped in this cursed prison. \n\nSorrow is abundant here, and therefore simple to obtain. You need only travel to Gorgoa. The damned shed copious tears that fall as crystalized grief as they are swept along the River of Souls.\n\nBe careful that their sadness does not overwhelm you.", progress = "Have you collected the tears?", completion = "The magnitude of the grief you have collected will bind the instrument to the Maw.", objectives = "Collect 10 Tears of the Damned from Gorgoa: The River of Souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63899] = { id = 63899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Book of Binding: The Mad Witch", description = "<You hear a muffled voice speaking from within this book, interspersed with crackling static. Though the utterances are mostly unintelligible, you can make out the repeated request to recover crimson pages.\n\nFlipping through the volume, you note that many of its pages are missing.\n\nIf the pages were retrieved, the book could be returned to the Archivist and reassembled.>", progress = "Is that book... speaking?", completion = "Scholars at the Seeker's Quorum were researching this tome.\n\nIt appears as though it was a fellow scholar, not mawsworn or wildlife, that tore it apart. This is troubling. \n\nFor our safety, I will stitch all but one missing page back into the binding before I add this to the archive. Until we know more about this relic, we cannot risk restoring it entirely.", objectives = "Collect 12 Crimson Pages, then bring them to Archivist Roh-Suir in the Reliquary of Remembrance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63901] = { id = 63901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Focusing the Eye", description = "The combination of grief and rage you have harvested is sufficient for your needs. Most likely. \n\nIf you insist on seeing this ill-advised endeavor through, use the horn at the Terminus Platform, where the River of Souls flows upward to Torghast. The energies there are most potent indeed.\n\nThe presence of your golden allies should draw the Jailer's Eye. I only hope this does not prove to be the end of you. I hate to see an investment wasted.", completion = "Songs will immortalize the deeds of this day, {name}.", objectives = "Go to the Terminus Platform and use the Ilskahorn to summon the Wrath of Odyn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63902] = { id = 63902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good News, Everyone!", description = "Come, friend. Let us be rid of this foul place.\n\nNo doubt your comrades will be eager to hear the news of the defeat of the Eye. I will bear you to them.\n\nGive the word when you are ready to depart, {name}.", progress = "What has happened?", completion = "The Eye defeated? Good news indeed.", objectives = "Fly with Danica to Korthia to give Bolvar the news.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63903] = { id = 63903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storming the Sanctum", description = "The Jailer has seized the sigils of all four covenants. It is clear he means to escape the Maw and steal the Arbiter's sigil from Oribos.\n\nWe cannot allow this to happen.\n\nAtop Torghast sits the Sanctum of Domination, the Jailer's seat of power. The time has come to enter this dark domain.\n\nNo doubt Sylvanas Windrunner will command the forces that will attempt to thwart us. We must defeat her... and save Anduin Wrynn from her grasp.\n\nGather your forces, {name}. The Ebon Blade will stand with you.", progress = "How fares the battle in the Sanctum?", completion = "The Jailer has what he wanted... along with Anduin at his side.\n\nOur only victory--if you can call it that--is that we have Sylvanas in custody.\n\nI pray she possesses knowledge that can give us an edge to stop whatever the Jailer is planning next.", objectives = "Defeat Sylvanas Windrunner in the Sanctum of Domination.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63904] = { id = 63904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of Ardenweald", description = "I hid my sigil in the Heart of the Forest, to keep it safe from the forces of the Maw.\n\nBut the horn has called for aid.\n\nYou and your allies go, see what has prompted the call.", progress = "Is my sigil safe?", completion = "Our best efforts were still in vain.\n\nOur enemy's plan edges closer to fruition.", objectives = "Investigate the Heart of the Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63908] = { id = 63908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bulwark of Divine Intent", description = "<Your familiarity with the Archivists' Codex confirms that this is one of the missing relics.\n\nArchivist Roh-Suir has a spot for this shield in the Reliquary of Remembrance.>", completion = "This shield is from the afterlife we refer to informally as the Inn of Forever.\n\nWhen one's spirit reaches the Inn, they hang up their arms. This shield was forever retired as its owner went to join the eternal fireside festivities. It would not quite be correct to say that the shield is imbued with their sense of duty and selflessness... it IS these concepts.\n\nI am curious whether this shield could be used in the field. The results of that testing would be fascinating. Perhaps someday...", objectives = "Bring the Bulwark of Divine Intent to Archivist Roh-Suir in the Reliquary of Remembrance.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63909] = { id = 63909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guise of the Changeling", description = "<Your familiarity with the Archivists' Codex makes it clear that this is one of the missing relics.\n\nArchivist Roh-Suir has a spot for this mask in the Reliquary of Remembrance.>", completion = "Now this is quite a find!\n\nThe Guise of the Changeling has the power to convincingly modify the appearance of its bearer, but it has a mind of its own. The wearer cannot control the illusion, and the mask is wont to place them into embarrassing or dangerous situations.", objectives = "Bring the Guise of the Changeling to Archivist Roh-Suir in the Reliquary of Remembrance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63910] = { id = 63910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Netherstar", description = "<You recognize this relic from the Archivists' Codex.\n\nThe power source is nearly empty. However, it could be restored with exposure to raw, unfiltered anima. Nearby fissures would do the trick.>", completion = "When we scholars consider relics that are important to keep secured, the Netherstar is precisely the type of relic that we have in mind. Can you imagine how much damage could be done were this to fall into the hands of an... opportunist?", objectives = "Recharge the Netherstar, then bring it to Archivist Roh-Suir in the Reliquary of Remembrance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63911] = { id = 63911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Singing Steel Ingot", description = "<The ingot wails, in a warbling vibrato.>\n\nWoe! These ruffians hammer upon me with nary a care, bending my body to suit their ill aims.\n\nFie! Fie upon them.\n\n<The ingot emits a high-pitched battle cry.>\n\nTake the hammering to these mawsworn!", completion = "In all of my years as a researcher, I never would have expected this.", objectives = "Defeat mawsworn invaders, then bring the Singing Steel Ingot to Archivist Roh-Suir in the Reliquary of Remembrance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63912] = { id = 63912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Celestial Shadowlands Chart", description = "<You recognize this relic from the Archivists' Codex.\n\nThe mawsworn discarded it, believing it to be useless.\n\nAnd the chart is useless, without the accompanying data to plot the relative locations of Shadowlands afterlives. If the research were retrieved from deceased scholars, the chart could be returned to the Archivist, fully functional.>", progress = "Is that the missing chart?", completion = "Aha! You have recovered the Celestial Shadowlands Chart.\n\nWith the chart and the data you collected, it can be restored to its fully functional form. It will take some time to analyze and interpret the results, which I can get started on now that the relic has been returned to the Archive.\n\nAllow me a moment to find a good spot for it...", objectives = "Collect 6 Afterlife Navigation Research scrolls, then bring them to Archivist Roh-Suir in the Reliquary of Remembrance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63913] = { id = 63913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unstable Explosive Orb", description = "<Your familiarity with the Archivists' Codex makes it clear that this is one of the missing relics.\n\nArchivist Roh-Suir has a spot for this device in the Reliquary of Remembrance.>", completion = "I appreciate you handling this relic carefully. It is nothing short of a miracle that it did not detonate when Korthia was invaded.", objectives = "Bring the Unstable Explosive Orb to Archivist Roh-Suir in the Reliquary of Remembrance.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63914] = { id = 63914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cipher of Understanding", description = "<Your familiarity with the Archivists' Codex makes it clear that this is one of the missing relics.\n\nArchivist Roh-Suir has a spot for the cipher in the Reliquary of Remembrance.>", completion = "My stars! To comprehend any of these languages would allow one the insight to translate all of them. We must look into this further.", objectives = "Bring the Cipher of Understanding to Archivist Roh-Suir in the Reliquary of Remembrance.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63915] = { id = 63915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drum of the Death Loa", description = "<Your familiarity with the Archivists' Codex makes it clear that this is one of the missing relics.\n\nArchivist Roh-Suir has a spot for this drum in the Reliquary of Remembrance.>", completion = "I could hear you approaching with this drum before I saw you. And strangely, I though someone else might be with you.", objectives = "Bring the Drum of the Death Loa to Archivist Roh-Suir in the Reliquary of Remembrance.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63916] = { id = 63916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sack of Strange Soil", description = "<Your familiarity with the Archivists' Codex makes it clear that this is one of the missing relics.\n\nArchivist Roh-Suir has a spot for this soil in the Reliquary of Remembrance.>", completion = "This soil can grow any type of plant, anywhere.\n\nNot the most dangerous relic missing from the archive, and yet it could be the most useful. With enough time, one could restore the verdant beauty of Korthia.", objectives = "Bring the Sack of Strange Soil to Archivist Roh-Suir in the Reliquary of Remembrance.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63917] = { id = 63917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everliving Statuette", description = "<Your familiarity with the Archivists' Codex makes it clear that this is one of the missing relics.\n\nArchivist Roh-Suir has a spot for this statuette in the Reliquary of Remembrance.>", completion = "I trust you did not listen to anything that this little monster told you.\n\nIt is absolutely incapable of uttering the truth.", objectives = "Bring the Everliving Statuette to Archivist Roh-Suir in the Reliquary of Remembrance.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63918] = { id = 63918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obelisk of Dark Tidings", description = "<Your familiarity with the Archivists' Codex makes it clear that this is one of the missing relics.\n\nArchivist Roh-Suir has a spot for this obelisk in the Reliquary of Remembrance.>", completion = "We must be cautious around this obelisk.\n\nMore than one attendant was driven mad while researching the relic.", objectives = "Bring the Obelisk of Dark Tidings to Archivist Roh-Suir in the Reliquary of Remembrance.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63919] = { id = 63919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Book of Binding: The Tormented Sorcerer", description = "<You hear a muffled voice speaking from within this book, interspersed with crackling static. Though the utterances are mostly unintelligible, you can make out the repeated request to recover azure pages.\n\nFlipping through the volume, you note that many of its pages are missing.\n\nIf the pages were retrieved, the book could be returned to the Archivist and reassembled.>", progress = "I find these strange speaking tomes... discomfiting.", completion = "This appears to be a companion tome to the crimson book that was under the care of scholars in the Seeker's Quorum.\n\nKnowing that this book binding was separated from its pages intentionally, I will stitch all but one azure page back into it before returning it to the archive.", objectives = "Collect 10 azure pages, then bring them to Archivist Roh-Suir in the Reliquary of Remembrance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63920] = { id = 63920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enigmatic Decrypting Device", description = "<Your familiarity with the Archivists' Codex makes it clear that this is one of the missing relics.\n\nArchivist Roh-Suir has a spot for this device in the Reliquary of Remembrance.>", completion = "Though I have only a passing understanding of its operation, this relic can strip the complexity of communication into a form that is free from subtlety, guile, or metaphor. Pure logic.", objectives = "Bring the Enigmatic Decrypting Device to Archivist Roh-Suir in the Reliquary of Remembrance.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63921] = { id = 63921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ring of Self-Reflection", description = "<Your familiarity with the Archivists' Codex makes it clear that this is one of the missing relics.\n\nArchivist Roh-Suir has a spot for this ring in the Reliquary of Remembrance.>", completion = "I am curious to learn how this strange ring functions.", objectives = "Bring the Ring of Self-Reflection to Archivist Roh-Suir in the Reliquary of Remembrance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63922] = { id = 63922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow Slicing Shortsword", description = "<Your familiarity with the Archivists' Codex makes it clear that this is one of the missing relics.\n\nArchivist Roh-Suir has a spot for this shortsword in the Reliquary of Remembrance.>", completion = "Though the blade's shadow severing properties may appear to be no more than a parlor trick, I believe this is one of the most dangerous relics in our care.", objectives = "Bring the Shadow Slicing Shortsword to Archivist Roh-Suir in the Reliquary of Remembrance.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63923] = { id = 63923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lang Family Wood-Carving", description = "<Your familiarity with the Archivists' Codex makes it clear that this is one of the missing relics.\n\nArchivist Roh-Suir has a spot for this wood-carving in the Reliquary of Remembrance.>", completion = "I believe this relic can teach us something about the history as well as the future.", objectives = "Bring the Lang Family Wood-Carving to Archivist Roh-Suir in the Reliquary of Remembrance.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63924] = { id = 63924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorak Claw Fetish", description = "<Your familiarity with the Archivists' Codex makes it clear that this is one of the missing relics.\n\nArchivist Roh-Suir has a spot for this fetish in the Reliquary of Remembrance.>", completion = "Some mote of Gorak Tul yet lives within this fetish. His corruption is barely contained.", objectives = "Bring the Gorak Claw Fetish to Archivist Roh-Suir in the Reliquary of Remembrance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63934] = { id = 63934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assail Mail", description = "Greetings, mortal!\n\nI am on a mission to deliver messages to our allies here in exciting Korthia. However, I was unable to complete my task.\n\nThe messages I was programmed to transport were stolen by Mawsworn, and then incorrectly stored all over the ground.\n\nWould you collect the messages and return them to me? I will then see them delivered to their intended recipients.\n\nThank you!", progress = "I must see my task completed.", completion = "These are the messages that were stolen! I commend you on recovering them.\n\nOh, there appears to be at least one extra...", objectives = "Retrieve 6 Stolen Messages from the Scholar's Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63935] = { id = 63935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precious Roots", description = "Korthia. A sister forest, stricken.\n\nBut in the throes of destruction, there is still hope. \n\nGather the anima, and build anew.", progress = "Sow growth.", completion = "Precious anima that will be shared. A sacrifice, honored.", objectives = "Collect 8 Residual Anima from around the Vault in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63936] = { id = 63936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Devoured Anima", description = "Sika has idea!\n\nDevourers... devour. They eat anything! So they eat anima, too.\n\nIf we take anima from devourers, then that anima is ours!", progress = "Sika wonders what anima tastes like.", completion = "Thank you! Wow... you can't tell this was inside devourer!\n\nSika will get anima to those most in need.", objectives = "Reclaim 12 Devoured Anima from devourers in the Estuary of Awakening.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63937] = { id = 63937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nasty, Big, Pointy Teeth", description = "There's tons of interesting things to kill out here! Bears, birds, mawsworn, and gromits!\n\nLet's start with the gromits shall we? Go slaughter the fierce gromits in the Mauler's Outlook and bring me their FANGS! I can always use more teeth.", progress = "I like the long teeth. Razor sharp fangs. The short ones are nice too.", completion = "EEEEEE! These are so good! Look how long and sharp they are! I am going to put these where they go right now! Thank you!", objectives = "Collect 6 Fierce Gromit Fangs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63944] = { id = 63944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korthia Awaits", description = "Ready yourself, {name}. Our allies await your arrival in Korthia.", completion = "Ah, yes. Your anima is rather familiar.\n\nWe were wondering when you would arrive.", objectives = "Report to Tal-Galan at Keeper's Respite in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63945] = { id = 63945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Soul Blade", description = "The runeblade of a Necrolord can be a potent weapon in this realm. An abundance of souls are willing to contribute their anima to end their own suffering and bring defeat to the Jailer.\n\nTake one of my runeblades and charge it with the anima of the willing souls you find here.\n\nOnce charged, use it lay waste to their forces here.", progress = "Has my blade tasted victory?", completion = "<Bonesmith Heirmir takes her runeblade back from you and examines it carefully.>\n\nNot bad, {name}. Always room for improvement... but not bad.", objectives = "Charge Heirmir's Runeblade with Willing Souls and use it to slay the Eye of Gorgoa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63949] = { id = 63949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shaping Fate", description = "The Jailer's power and malevolence continue to grow. So must our resilience.\n\nStand amongst your allies, {name}. Push back against the darkness that would consume us all.\n\nTogether, we will yet prevail.\n\nMay the Purpose guide your hand.", progress = "One cannot run from history, but one's actions may shape the outcome.", completion = "The threads of fate weave through you, Maw Walker.\n\nJust as the prophecies foretold.", objectives = "Thwart the Jailer's efforts throughout Korthia and the Maw by completing Covenant Assaults, Daily Quests, looting treasures, slaying rare creatures, and defeating Tormentors of Torghast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63950] = { id = 63950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Razorwing Talons", description = "These lands are not well known yet by my hunters, but we have discovered formidable beasts that reside here.\n\nAmong these are the Razorwing: vicious predators with terrible talons... and the temper of a vorkai.\n\n<Herne grins fiercely.>\n\nBring me some of their talons to help teach our newest hunters about the kinds of beasts they will face.", progress = "Do you have those Razorwing Talons?", completion = "These talons are in excellent shape. And they look like they could take out an eye! <Herne chuckles ironically.>\n\nI expect they will get a lot of attention from our Wild Hunt recruits.\n\nThank you, Maw Walker.", objectives = "Collect 10 Razorwing Talons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63951] = { id = 63951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shady Place", progress = "There is much we cannot see.", completion = "Excellent work Maw Walker." }
quests[63952] = { id = 63952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heavy-Handed Tactics", description = "We need more constructs on the front lines, but we have no bodies, heads, or legs! \n\nRathan's making the best constructs possible with what we DO have... a lot of hands.\n\nDon't ask questions!\n\nThere are enemies in Calcis that we need dead. Take the hands and kill things!", progress = "Rathan is nothing if not resourceful.", completion = "<Margrave Sin'dane looks impressed... or annoyed... or disgusted... or concerned?>\n\nHm. I suppose with enough hands, anything IS possible...", objectives = "Slay 8 Mawsworn Soulbreakers, 4 Crystalline Guardians, Lady Nalis, and Glassmaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63953] = { id = 63953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korrak's Revenge" }
quests[63954] = { id = 63954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealed Secrets", description = "Ah, Korthia. What secrets will be revealed?\n\nMy associates have been hard at work, seeking to discover and procure various small items of interest throughout this broken land. Nothing of great importance, I assure you.\n\nThey have secured those items in designated drop boxes, and those now await pickup in Seeker's Quorum. Don't worry, they are locked with an impenetrable seal to protect both the contents and the deliverer.\n\nBring those sealed containers to me, and I will reward you handsomely.", progress = "Do you have the sealed containers?", completion = "Wonderful! You brought everything that I asked for.\n\nAgain, do not worry about the contents of these boxes. They pose no threat to you.\n\nHere is the reward I promised.", objectives = "Retrieve 5 Sealed Containers from the Seeker's Quorum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63955] = { id = 63955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealed Secrets", description = "Ah, Korthia. What secrets will be revealed?\n\nMy associates have been hard at work, seeking to discover and procure various small items of interest throughout this broken land. Nothing of great importance, I assure you.\n\nThey have secured those items in designated drop boxes, and those now await pickup outside of the Vault. Don't worry, they are locked with an impenetrable seal to protect both the contents and the deliverer.\n\nBring those sealed containers to me, and I will reward you handsomely.", progress = "Do you have the sealed containers?", completion = "Wonderful! You brought everything that I asked for.\n\nAgain, do not worry about the contents of these boxes. They pose no threat to you.\n\nHere is the reward I promised.", objectives = "Retrieve 5 Sealed Containers from the Vault in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63956] = { id = 63956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealed Secrets", description = "Ah, Korthia. What secrets will be revealed?\n\nMy associates have been hard at work, seeking to discover and procure various small items of interest throughout this broken land. Nothing of great importance, I assure you.\n\nThey have secured those items in designated drop boxes, and those now await pickup in the Windswept Aerie. Don't worry, they are locked with an impenetrable seal to protect both the contents and the deliverer.\n\nBring those sealed containers to me, and I will reward you handsomely.", progress = "Do you have the sealed containers?", completion = "Wonderful! You brought everything that I asked for.\n\nAgain, do not worry about the contents of these boxes. They pose no threat to you.\n\nHere is the reward I promised.", objectives = "Retrieve 5 Sealed Containers from the Windswept Aerie in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63957] = { id = 63957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Observational Records", description = "Greetings, Maw Walker, a moment of your time?\n\nAs you no doubt know, my cartel has quietly spread observational devices all across Korthia. But that data is no good to us if it is not retrieved. Which is where you come in.\n\nThe Seeker's Quorum records should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb.\n\nBring those data to me, and I will reward you handsomely.", progress = "Have you retrieved the observational records from Seeker's Quorum?", completion = "The name \"Seeker's Quorum\" has puzzled me greatly since I learned of it. What are they seeking? What constitutes a Quorum? What did they do there?\n\nThese mysteries may be beyond us, or they may yet be revealed. And here is your reward, as promised.", objectives = "Collect 5 Observational Records from Seeker's Quorum in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63958] = { id = 63958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Observational Records", description = "Greetings, Maw Walker, a moment of your time?\n\nAs you no doubt know, my cartel has quietly spread observational devices all across Korthia. But that data is no good to us if it is not retrieved. Which is where you come in.\n\nThe records from outside the Vault should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb.\n\nBring that data to me, and I will reward you handsomely.", progress = "Have you retrieved the observational records from the Vault?", completion = "The Vault is reason why the Jailer targeted Korthia with his chains. Many secrets of the Shadowlands are archived there.\n\nIf we can just get a glimpse of how it works and what it holds, that information would be most valuable indeed.\n\nAnd here is your reward, as promised.", objectives = "Collect 5 Observational Records from outside the Vault in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63959] = { id = 63959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Observational Records", description = "Greetings, Maw Walker, a moment of your time?\n\nAs you no doubt know, my cartel has quietly spread observational devices all across Korthia. But that data is no good to us if it is not retrieved. Which is where you come in.\n\nThe Sanctuary of Guidance records should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb.\n\nBring those data to me, and I will reward you handsomely.", progress = "Have you retrieved the observational records from the Sanctuary of Guidance?", completion = "The devourers have destroyed much of what might have been useful at the Sanctuary of Guidance. But this information will still prove valuable.\n\nAnd here is your reward, as promised.", objectives = "Collect 5 Observational Records from the Sanctuary of Guidance in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63960] = { id = 63960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Observational Records", description = "Greetings, Maw Walker, a moment of your time?\n\nAs you no doubt know, my cartel has quietly spread observational devices all across Korthia. But that data is no good to us if it is not retrieved. Which is where you come in.\n\nThe records from the Windswept Aerie and Estuary of Awakening should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb.\n\nAnd don't forget to look below ground!\n\nBring those data to me, and I will reward you handsomely.", progress = "Have you retrieved the observational records from the Windswept Aerie and Estuary of Awakening?", completion = "Places like the Aerie and Estuary must have been desolate even before all the destruction. What interesting creatures congregate there.\n\nWill they all survive these changes? Will some adapt, and become even more fearsome?\n\nHere is your reward, as promised.", objectives = "Collect 5 Observational Records from the Windswept Aerie and Estuary of Awakening in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63961] = { id = 63961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealed Secrets", description = "Ah, Korthia. What secrets will be revealed?\n\nMy associates have been hard at work, seeking to discover and procure various small items of interest throughout this broken land. Nothing of great importance, I assure you.\n\nThey have secured those items in designated drop boxes, and those now await pickup in Mauler's Outlook. Don't worry, they are locked with an impenetrable seal to protect both the contents and the deliverer.\n\nBring those sealed containers to me, and I will reward you handsomely.", progress = "Do you have the sealed containers?", completion = "Wonderful! You brought everything that I asked for.\n\nAgain, do not worry about the contents of these boxes. They pose no threat to you.\n\nHere is the reward I promised.", objectives = "Retrieve 5 Sealed Containers from Mauler's Outlook in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63962] = { id = 63962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Observational Records", description = "Greetings, Maw Walker, a moment of your time?\n\nAs you no doubt know, my cartel has quietly spread observational devices all across Korthia. But that data is no good to us if it is not retrieved. Which is where you come in.\n\nThe records at Mauler's Outlook should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb.\n\nBring those data to me, and I will reward you handsomely.", progress = "Have you retrieved the observational records from Mauler's Outlook?", completion = "Excellent, this data will serve us well. We can begin to answer some of our questions about Korthia, and the Mauler's Outlook. Was it always home to such terrible creatures, or did was it something more?\n\nAnd here is your reward, as promised", objectives = "Collect 5 Observational Records from Mauler's Outlook in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63963] = { id = 63963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broker's Bounty: Ripmaul", description = "New lands bring new opportunity. To any interested party, we will provide a quantity of valuables in return for a piece of heavily spiked hide from the beast known as Ripmaul.\n\nFaint-hearted collectors need not bother.\n\nPlease bring this sample to Ta'nasi in Keeper's Respite.", progress = "Have something to trade?", completion = "<Ta'nasi tugs at the spiked hide to test its strength.>\n\nAn excellent specimen. This will do nicely.\n\nAnd as promised, here is your reward in trade.", objectives = "Retrieve a Heavy Spiked Hide from Ripmaul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63964] = { id = 63964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broker's Bounty: Grimtalon", description = "New lands bring new opportunity. To any interested party, we will provide a quantity of valuables in return for an intact boney beak from the beast known as Grimtalon.\n\nFaint-hearted collectors need not bother.\n\nPlease bring this sample to Ta'nasi in Keeper's Respite.", progress = "Have something to trade?", completion = "<Ta'nasi knocks the sturdy beak against her palm, listening to the sound.>\n\nAn excellent specimen. This will do nicely.\n\nAnd as promised, here is your reward in trade.", objectives = "Retrieve a Mature Ossified Beak from Grimtalon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63965] = { id = 63965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Razorwing Egg Rescue", description = "I'm amazed by the wildlife here in Korthia! So many interesting creatures...\n\nSay, you know those flying beasts with the claws, the Razorwing? They sometimes knock their eggs out of their nests, and then they completely ignore them! If you find any abandoned eggs, could you bring them to me?\n\nGently, of course. I wonder if they can be raised to be friendly?\n\nIf not, well, it wouldn't be the first time I've had my antennae chewed on.", completion = "Look at these wonderful eggs! I can hear their heartbeats.\n\nThis is the start of something beautiful, I just know it.", objectives = "Collect 5 Razorwing Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63968] = { id = 63968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clean Out the Crucible", description = "The Winter Queen has called a hunt. We will ensure that the Crucible of the Damned is rid of the Jailer's forces today.\n\nDo your part and hunt down any enemies you find.", completion = "The hunt is not yet complete, but you have earned your place in the records of its victory.", objectives = "Kill 30 enemies in the Crucible of the Damned and Calcis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63969] = { id = 63969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looming Darkness", description = "The Winter Queen called for a hunt in this location due to reports of a massive, unnatural darkness swelling in its upper regions.\n\nThe Wild Hunt is brave, but not foolish. We must learn what we can about this darkness before we charge into it.\n\nSearch the bodies of our enemies nearby for clues.", progress = "Have you learned anything regarding the darkness yet?", completion = "We will discover the source of this darkness, and end it.", objectives = "Collect 1 Mawsworn Ritual Book, 10 Mawsworn Missive Scraps, and 15 Dark Marrow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63970] = { id = 63970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Soul Left Behind", description = "Do you hear the cries of tormented souls trapped in Gorgoa?\n\nThe twisted river of souls flows before us, swelling with cruelty and the torment of undeserving victims.\n\nOur brave regiment of druid spirits led the charge into the river to seek out those lost souls, but I fear many have instead joined in their suffering.\n\nSummon your courage and take my cradle with you into the river. Load the lost souls you find onto the cradle, then order the cradle to come back to me.", progress = "I admire Thiernax's dedication to even the least among us.", completion = "Thank you, {name}. We must not forget to help one another as we stride deeper into the darkness.", objectives = "Use Thiernax's Rescue Cradle to rescue 12 Lost Druids in Gorgoa and send them back to Thiernax.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63971] = { id = 63971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snail Stomping", description = "Careful where you step. You wouldn't want to accidentally squish a Mawsworn, would you?\n\nOf course you would! It's so fun!\n\n<Lady Moonberry giggles and points at the snails around her.>\n\nIt's so much easier to squish Mawsworn after you've transformed them into stinky little snails.\n\nHere, take my wand and try it out on whatever you like.\n\nYou may need to weaken them a bit first, but it'll work on almost anything!", progress = "Lady Moonberry never ceases to surprise me.", completion = "<Lord Herne grins.> My record was squishing four in a single jump.\n\nOne of the many benefits of being a quadruped.", objectives = "Use Lady Moonberry's Wand to transform 15 weakened enemies into snails, and then squish them!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63972] = { id = 63972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Don't Ask Me to Spell It", description = "It's getting dangerous out there for druid spirits!\n\nThankfully, we always have room for another friend in our group, and this fine tirnenn has offered to help me and the gang get around the battlefield safely.\n\n<The tirnenn behind Choofa begins speaking slowly, but Choofa just talks louder.>\n\nGood ol' Kirriprkar- I mean, Karripkraker- I mean, Krackerkrisp...\n\n<Choofa laughs.>\n\nLet's just call her \"Big K\"!\n\nHop on, everybody!", progress = "Krrprripripkraak and Choofa are teaming up? This, I must see.", completion = "I have received many reports from hunters who were aided by Krrprripripkraak and her friends. Thank you for helping them.", objectives = "Help Krrprripripkraak and her friends sow chaos in the Crucible of the Damned.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63973] = { id = 63973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Double Dromans", progress = "You can find the droman up the hill from here.", completion = "No matter how strong we become, we are stronger when we hunt together.", objectives = "Help Droman Aliothe defeat enemies along her path and kill Lord Dretnal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63974] = { id = 63974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's Going to Sting", description = "<Niya speaks loudly to be heard over the buzzing coming from the collection of needler nests behind her.>\n\nI've caught Moonberry trying to steal these nests for her pranks over ten times already!\n\nThe other faeries said I was crazy to bring the needlers out here. Too wild! Too unpredictable!\n\nBut that's exactly why we need them.\n\nLord Herne's scouts report powerful Heralds among our enemy's forces.\n\nTake one of these nests, and use it to surprise the Heralds!", progress = "Niya is proving to be quite the clever tactician...", completion = "I wish I could've been there to see it myself!\n\nA fitting end for the Heralds...", objectives = "Use an Angry Needler Nest to weaken and kill Herald Gkeca, Herald Throgtu, and Herald Duarri.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63976] = { id = 63976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Al'ley Cat of Oribos", description = "Ah, Maw Walker. I have a message.\n\nAn individual has a proposition for you, specifically. I know nothing of the details, only that they asked you meet them towards the back of the Idyllia.", completion = "It is a pleasure to meet you.", objectives = "Meet with the mysterious contact in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63977] = { id = 63977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insider Trading", description = "I am the foremost expert on broker culture. However, relationships between cartels are complicated and unstable.\n\nCartel So holds a small presence here in Oribos, which means the other cartels may have knowledge that I do not. Ask around--with your renown, surely they'll have whatever information that we are missing.", progress = "Have you had a chance to speak with the other cartels?", completion = "How rude! They should be aware of who they are talking to.\n\nI apologize for my kin, Maw Walker.", objectives = "Speak with various broker cartels around Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63979] = { id = 63979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Things Best Kept Dark", description = "The leader of Cartel So represents a grave danger to the Shadowlands, Maw Walker.\n\nHer name is So'leah. She seeks to assemble an artifact of the First Ones and use its power for selfish ends.\n\nPieces of the relic are said to be hidden on your homeworld. Brokers have never before found our way there. But if So'leah does, then Azeroth too is imperiled.\n\nWe must intercept her.\n\nThere is cargo nearby marked for Cartel So. Perhaps the manifest will give us clues as to their leader's whereabouts.", progress = "Have you found anything?", completion = "Tazavesh, the Veiled Market...\n\nAn interesting choice of locations.", objectives = "Find a shipping manifest belonging to Cartel So.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63980] = { id = 63980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Smugglers", description = "We brokers have found that it is in our best interests to remain mobile. And discreet.\n\nA number of our cities and outposts are tucked away in the In-Between, capable of moving from place to place.\n\nMuch to my chagrin, it seems I have lost track of Tazavesh.\n\nI believe our best course of action is to ask Cartel Ta for access. They pride themselves on keeping track of such things.\n\nLet's try our luck with those at the Night Market in Revendreth. They may be more forthcoming than their Oribos kin.", completion = "You seek information?\n\nThat requires a transaction.", objectives = "Speak with Ta'nla the Identifier at the Night Market.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63982] = { id = 63982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Above My Station", description = "While I indeed know the location of the Veiled Market, I fear I can do little in terms of providing you with transportation to it.\n\nIn return for your assistance with a task, I can send you to someone who can assist us both. There is a bounty hunter at Transfer Station Ta--a broker enclave in Bastion. He is better suited to help you... and he owes me a shipment.\n\nMeet with Ta'oku and tell him that Ta'nla sent you.\n\nFor your convenience, I can offer use of a portal. After all, we are partners, yes?", completion = "Need something hunted down?", objectives = "Take the portal at the Night Market and speak with Ta'oku.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63983] = { id = 63983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dead Drop", description = "Ta'nla requested something very... specific... on behalf of a client.\n\nThe kyrian have been working on a new type of centurion they call an aquilon. I sent some of our trade specialists to retrieve the prototype in question, but they have yet to return. \n\nUntil I have the item, there is obviously no way I can ship it to Ta'nla. Perhaps we can help one another.\n\nIf you can locate the aquilon and bring it here, I will help you reach Tazavesh.", progress = "Have you acquired the... item?", completion = "Perfect! This will put us back on schedule.", objectives = "Retrieve the Prototype Aquilon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63984] = { id = 63984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coins for the Ferryman", description = "Your side of the deal is done, Maw Walker. Now for your payment.\n\nMy cartel runs a ferry that travels between Oribos and Tazavesh. Its purpose is to transport cargo, but as in all things, there are... exceptions.\n\nTake this coin to Ta'meri and you will be provided safe passage to the market.\n\nWhat happens after that is up to you.\n\n<Ta'oku bows, uttering a sound that seems almost like a chuckle.>", completion = "Maw Walker! What can humble Ta'meri do for you?", objectives = "Speak with Ta'meri in Oribos.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63985] = { id = 63985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Veiled Market", description = "Let me guess... Ta'oku sent you my way, yes? \n\n<Ta'meri looks at the coin you offer.>\n\nSo, you seek travel to Tazavesh. Not something we'd typically offer an outsider, but since payment has been accounted for, it would be my pleasure to assist you.\n\nStep aboard, and do remember to keep any appendages inside the craft at all times. The currents of the In-Between can be fickle.", completion = "No worries! I have another plan.", objectives = "Ride the barge to Tazavesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63986] = { id = 63986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tazavesh: Raiders of the Lost Artifact", description = "It looks like you may need to show a bit of force once more, my dear friend. Tazavesh security will not let us simply walk in.\n\nBut So'leah needs to be stopped. If that requires a bit of physical... persuasion... then it is a necessary evil. \n\nBring some friends. I have a feeling the security here has tricks up their sleeves.", objectives = "Enter Tazavesh and defeat So'leah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63987] = { id = 63987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ve'lor's Lost Parcel" }
quests[63989] = { id = 63989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oozing with Character", description = "Apprentice! I've been looking for you.\n\nKevin has been such a wonderful helper in our experiments, I'd like to train my other oozes to be able to assist as well!\n\nCan you take Plaguey with you and test their ability to infect organic life forms?", progress = "They're good oozes, {name}.", completion = "How did Plaguey do? Is he as viral as we'd hoped?", objectives = "Help Plaguey test their infection ability in the Mauler's Outlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63990] = { id = 63990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blade in the Night", description = "Though my hunt has been arduous, I have two promising leads on additional Night Warriors. The first is here in Maldraxxus.\n\nThis tower contains records of those who arrived in Maldraxxus, including someone referred to as \"The Blade in the Night.\" I believe this to be our next Night Warrior.\n\nI encountered many traps on the way here. Doubtless we will find more within the tower. Someone is trying to stop us.\n\nWe will not let them succeed.", progress = "Hmm.", completion = "I am not opposed to helping you, but... There are matters I must attend to first.", objectives = "Search the Sepulcher of Knowledge for clues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63994] = { id = 63994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who is the Maw Walker?", description = "Korthian prophecies foretell the arrival of a Maw Walker who can save us from disaster. \n\nPerhaps this is that day. But perhaps not. I must test your anima to verify your claim.\n\nIf you speak the truth, then I have a solemn duty to empower your anima before we proceed.", progress = "Let us proceed, Maw Walker.", completion = "Maw Walker. We must summon the others.", objectives = "Participate in Tal-Galan's Maw Walker trial.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64006] = { id = 64006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nav Test: Zereth Mortis", description = "This quest will take you through a likely flow for the 9.2 Main Line questing. We don't have a finalized pitch for the 9.2 Main Line yet, so this is just a rough idea of how the POIs might be used.\n\nThis test is built to be Beastmaster and Godmode friendly, so feel free to use cheats.\n\nUseful cheats:\n92BrokerTown - Return to hub\n92NavTest - Restart the Nav Test (Must abandon first)" }
quests[64007] = { id = 64007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charge of the Covenants", description = "Thanks to the efforts of you and other heroes of Azeroth, the covenants have grown strong. But we can no longer afford to wait for the Jailer to make his next move.\n\nThe way to the Maw is open. Our forces stand ready.\n\nThe covenants await your signal, {name}.", completion = "The Maw...\n\nNow our true work begins.", objectives = "Rally the covenant forces to go into the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64012] = { id = 64012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies from Death's Advance", description = "Your work toward stopping the Jailer's advances has not gone unnoticed. If it is power you seek to continue your efforts I believe I can be of some assistance.", completion = "Your work toward stopping the Jailer's advances has not gone unnoticed. If it is power you seek to continue your efforts I believe I can be of some assistance.", objectives = "Speak with Duchess Mynx at Keeper's Respite in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64014] = { id = 64014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mawsplaining", description = "There remains one task now before the glorious battle can begin. The horn must be anchored to the Maw so that its voice may pierce the barrier that surrounds that foul realm. \n\nHow this can be done, I do not know. Seek out one that understands the mysteries of that place. Surely they can guide your hand.\n\nDanica and her sisters will listen for Ilskahorn's call. They will answer when you need them, {name}.", progress = "Have you bound the horn to the Maw?", completion = "That's quite an instrument you have there.\n\nIt seems the golden feathers were worth following, Maw Walker. You owe me yet again.", objectives = "Ask Ve'nari's help to bind the Ilskahorn to the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64015] = { id = 64015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Meat Grinder", description = "All these mawsworn have got me excited for some slaughter!\n\nI've got a plan that probably won't end in you dying.\n\nAre you in?", completion = "Bwahahaha!\n\nSo much slaughter, so many parts! You've been a real strong arm today, {name}.", objectives = "Lay a trap for the Mawsworn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64016] = { id = 64016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oozing with Character", description = "Apprentice! I've been looking for you.\n\nKevin has been such a wonderful helper in our experiments, I'd like to train my other oozes to be able to assist as well!\n\nFor Ooz, I'd like to know if they are able to consume organic material and increase in size.", progress = "They're good oozes, {name}.", completion = "How did the tests go? OH! Ooz! You're huge! You're even more beautiful than normal!", objectives = "Help Ooz test their growth ability on Shardhide in the Mauler's Outlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64017] = { id = 64017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oozing with Character", description = "Apprentice! I've been looking for you.\n\nKevin has been such a wonderful helper in our experiments, I'd like to train my other oozes to be able to assist as well!\n\nFor Bloop, I'd like to know if their ooze is capable of propagation. Take them with you, and find those bears. Give them the command to inject the life form with their ooze and see what happens.", progress = "They're good oozes, {name}.", completion = "How did the tests go? OH! Look at all of them! They're so cute!", objectives = "Help Bloop test their propagation ability in the Mauler's Outlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64018] = { id = 64018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Weight of Stone", completion = "You did it!", objectives = "Assist the Stone Legion in delivering supplies and anima.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64040] = { id = 64040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Once More, with Healing", description = "The mawsworn continue to engage our forces at the Vault. There are heavy casualties on both sides. We must help!\n\nTake this and restore any wounded covenant allies you find. Mikanikos helped me create it. It runs on anima and should help patch up anyone. Even the Stoneborn or Maldraxxi.", progress = "I wish we could do more. But we're stretched so thin.", completion = "How wonderful! I am relieved to know our allies are no longer wounded.", objectives = "Restore 10 Wounded Covenant Allies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64042] = { id = 64042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rituals of Night", description = "Tyrande's time grows short, so we must act quickly. \n\n<Ysera frowns in concern.>\n\nWe had hoped to gather more Night Warriors, but we will have to proceed with who we have and hope it is enough.\n\n<Ysera shakes her head, then looks more resolute.>\n\nBefore we can begin, we must finish preparations for the ritual. Please bring these last few items with you and meet us at the grove.", progress = "Good, we may begin.", completion = "With everything in place we can begin. I only hope we are not too late for Tyrande.", objectives = "Assist with the preparations and ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64043] = { id = 64043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Need a Healer - You!", description = "There are too many wounded on the battlefield! \n\nNot everyone can 'bash it and make better.' We need more healers.\n\nYou: take my device and get our wounded back on their feet!", completion = "That got them back on their feet!\n\nAny little bit helps to keep us in the fight.", objectives = "Restore 10 Wounded Covenant Allies in Seeker's Quorum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
